window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"id":"syllabus-office-exchange","chapter":3,"section":"3.1","origin":"syllabus","topic":"考纲补充","title":"编辑源文件、纯文本和固定版面文档各有用途","conclusion":"DOCX适合保留Word文档的结构、样式和对象供继续编辑；TXT主要保存纯文本，不保留复杂排版；PDF常用于保持页面外观、阅读或打印。","points":["DOC是较早的Word格式；RTF支持一定的文本格式交换。选择交换格式前，应看对方需要继续编辑、保留结构还是核对固定版面。","WPS Office也提供文字、表格和演示工具；跨软件打开文件后，应检查字体、分页、公式、图表、动画等关键结果，不能仅凭扩展名相同就保证完全一致。","Word、WPS文字适合连续文稿、样式、目录和页面排版；Excel、WPS表格适合按行列组织数据、公式计算、筛选汇总与图表；PowerPoint、WPS演示适合按幻灯片组织讲解。","教学示例：班级成绩录入和平均分计算放在表格软件；分析报告放在文字软件；面向全班展示结论使用演示软件。报告中的表格不因此等同于Excel工作簿。","先新建相应类型文件，再按需要保存可编辑源文件。Office常用源格式分别是DOCX、XLSX、PPTX；跨软件交换后检查字体、公式、图表和动画是否保持。","新建与打开：在Windows桌面Word2016中，启动后选择“空白文档”，或在Word中按Ctrl+N新建文档；按Ctrl+O，或用文件→打开，找到已有文件所在位置并打开。新建是从一份新文档开始，打开是继续处理已有文件；进入后先核对文件名和正文，避免把相似文件当成同一份。","保存与另存为：首次保存可用文件→另存为，选择“此电脑”下的文件夹或“浏览”，填写文件名并核对保存类型后保存；普通可编辑Word文档常用.docx。继续修改当前文件时按Ctrl+S，或单击快速访问工具栏的保存。需要保留另一版本、换位置或换格式时，用文件→另存为，或按F12打开另存为对话框，明确设置目标文件名、位置和类型；要保留原稿，就给新版本不同的文件名或位置。完成后核对当前文件身份，不能把保存当前文件当作已经生成另一份副本。"],"boundary":"这里是文档常见格式的教学概括；兼容情况取决于具体版本和文件使用的功能。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2021q56","label":"样式统一一份文档，模板给多份文档共同起点","reason":"DOCX是可编辑文档，DOTX/DOTM是供新文档复用的模板；从模板新建与打开模板修改影响的文件不同。"}],"pointGroups":[{"title":"先按任务选文字、表格或演示软件","indices":[2,3,4]},{"title":"Word文档的新建、打开与保存","indices":[5,6]},{"title":"文件格式与跨软件交换","indices":[0,1]}],"pointPresentation":{"5":{"title":"新建文档与打开已有文件","navigationLabel":"新建与打开"},"6":{"title":"保存当前文件与另存版本","navigationLabel":"保存与另存为","blocks":[{"label":"首次保存"},{"label":"继续保存当前文件","from":"继续修改当前文件时"},{"label":"另存版本、位置或格式","from":"需要保留另一版本"},{"label":"保存后核对","from":"完成后核对"}]}}},{"q":7,"chapter":3,"section":"3.2","type":"单选","topic":"文本选择","title":"Ctrl+Shift+End选到文档末尾","trigger":"题目要求从当前插入点一次选择到Word文档末尾。","conclusion":"在Word中，Ctrl+Shift+End从当前插入点扩展选择到文档末尾；Ctrl+End只移动光标而不选择。","points":["Shift负责扩展选择，Ctrl+方向或Home/End负责跨更大范围移动。","Ctrl+Shift+Home可从当前位置选择到文档开头。","Shift+End通常只选择到当前行末。","连续选择：可左键拖过文字，或先单击起点，再按住Shift单击终点。需要不连续片段时，先选第一处，再按住Ctrl拖选后续片段；注意Ctrl在正文中单击通常用于选中一句，不能和Ctrl拖选混淆。矩形文本区域可按住Alt拖选，这也不是普通连续选区。","鼠标位置决定选择单位。在正文中双击通常选一个词，三击选一个段落，Ctrl单击选一句；在正文左侧选定栏（指针朝向正文时）单击选一行、双击选一段，三击或Ctrl单击选全文。中文分词边界可能与直觉不同，执行删除或格式命令前核对高亮范围。","Home、End通常移动到当前行首、行末；Ctrl+Home、Ctrl+End移动到文档开头、末尾。加入Shift表示从原插入点扩展选择：Shift+Home/End选到行首/行末，Ctrl+Shift+Home/End选到文首/文末。Ctrl+A选择全文；鼠标单击新位置通常取消原选区并重新定位。","定位到已知位置可按Ctrl+G或F5打开“定位”，选择页、节、行或书签等目标，输入编号后定位；这是移动插入位置，不等于选中该页全部内容。Ctrl+F偏向按文字查找和导航，Ctrl+H进入替换。"],"boundary":"Home/End的作用范围会受Ctrl和Shift组合影响，答题时要同时检查“移动到哪里”和“是否选择”。","id":"y2024q7","sources":[{"year":2024,"q":7,"type":"单选"}],"keys":["2024-7"],"related":[{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"连续键盘选区与按样式跨位置选区服务不同批量任务，先确认目标范围再删除或改格式。"},{"id":"syllabus-word-text-editing","label":"输入、复制与移动","reason":"先选对对象，再按完整操作链改稿。"}],"pointGroups":[{"title":"键盘移动与选择的核心规则","indices":[5,0,1,2]},{"title":"鼠标选择与选定栏","indices":[3,4]},{"title":"按位置定位","indices":[6]}],"searchAliases":["选定栏","矩形选择","不连续文本","Ctrl+A","Shift+单击","Alt+拖动","Ctrl+G","F5","Home","End"]},{"id":"syllabus-word-text-editing","chapter":3,"section":"3.2","origin":"syllabus","type":"知识补充","topic":"输入与剪贴板","title":"正文编辑：先定位和选择，再输入、复制或移动","conclusion":"插入点决定输入位置，选区决定被替换或处理的内容；复制保留原文，剪切后原文先移除，粘贴把内容放到新的插入位置。","points":["先单击正文放置插入点，再输入文字。插入模式下，新文字推开后面的内容；已有选区时，直接输入通常替换选中文字。开始改稿前先确认是否仍有高亮选区，不能把“有光标”理解为一定没有选择。","没有选中文字时，Backspace删除插入点前的内容，Delete删除后面的内容；已有选区时，两者都可删除所选文本。若删除的是段落标记，原先两个段落会合并，应检查合并后的段落格式；不要把表格中删除内容与删除结构的规则套到普通正文。","改写模式会用新输入覆盖后面的已有文字。Word2016中，文件→选项→高级→编辑选项可设置“使用改写模式”；只有启用“用Insert键控制改写模式”时，Insert才按这一设置切换。不是每台Word按一次Insert都会改写。","复制文字：选中源文字→Ctrl+C（或开始→剪贴板→复制）→单击目标位置→Ctrl+V→核对两处文字。移动文字：选中→Ctrl+X剪切→确定目标位置→Ctrl+V→核对新位置和原位置。正文文本剪切通常立即从编辑区移除，与资源管理器先把文件标记为待移动的时机不同。","也可先选中文字，指向选区后左键拖到目标插入位置来移动，按住Ctrl拖动来复制；要观察插入标记和复制提示。此操作受Word“允许拖放式文字编辑”等设置影响，不能把Windows文件跨卷拖放的默认规则套到正文。手机网页的长按选词与桌面Word鼠标选区不是同一交互。","粘贴后核对内容及格式。“保留源格式”保留复制处格式；“合并格式”采用目标样式，但可能保留原文局部加粗、倾斜等强调；“只保留文本”舍弃原字符格式及图形，文字仍按目标位置格式显示，不是完全没有格式，也不能保留图片或完整表格外观。Word2016的Ctrl+Shift+V用于粘贴格式，不应按新版Microsoft365的纯文本粘贴快捷键记忆。","开始→剪贴板组的对话框启动器可打开Office剪贴板，最多收集24项，可选择其中一项粘贴，也可全部粘贴或清空。继续收集超出容量时会移走最早项目；它与Windows的当前剪贴板及Win+V历史不是同一个列表。普通粘贴不会自动清空所复制的文本，可再次粘贴；不要把它当长期保存文稿的方式。","需要撤销最近编辑时按Ctrl+Z，先观察是否撤回了目标动作；撤销后可用Ctrl+Y重做仍可重做的动作。重做与重复当前命令有不同语境，撤销栈也不是永久版本备份；重要改动前保存文档，不能假定任何操作都可无限撤销。","输入键盘上没有的字符，可用插入→符号→其他符号，选择字体和字符后插入；能否显示取决于字体支持。插入一个带圈数字是字符内容，不会自动建立可连续编号的段落列表。"],"boundary":"本卡讲普通可编辑正文；表格、受保护区域、域与图形对象另有操作边界。选区和键盘移动练习见关联卡片；网页不模拟系统剪贴板或完整Word编辑器。","sources":[],"keys":[],"searchAliases":["插入点","选区替换","Delete","Backspace","改写模式","Insert","Office剪贴板","24项","只保留文本","Ctrl+X"],"trigger":"按2026年考试要求与已核查课堂范围补充；操作以Windows桌面Word2016为基线，具体来源见参考资料。网页演示不等于真实Word实测。","pointGroups":[{"title":"输入、删除与改写","indices":[0,1,2]},{"title":"复制、移动与粘贴的完整链","indices":[3,4,5]},{"title":"剪贴板、撤销与特殊字符","indices":[6,7,8]}],"related":[{"id":"y2024q7","label":"练习真实文本选区","reason":"单击定位、拖选并比较行首行末与文首文末。"},{"id":"y2025q48","label":"批量改词与格式","reason":"从单次修改过渡到核对查找条件后批量处理。"}],"pointPresentation":{"3":{"title":"复制与移动文字","navigationLabel":"复制与移动","blocks":[{"label":"复制：保留原文","steps":["复制文字：选中源文字","Ctrl+C","单击目标位置","Ctrl+V","核对两处文字"]},{"label":"移动：改变文字位置","from":"移动文字：","steps":["移动文字：选中","Ctrl+X","确定目标位置","Ctrl+V","核对新位置"]},{"label":"剪切后发生什么","from":"正文文本剪切"}]},"4":{"title":"用鼠标拖动文字","navigationLabel":"拖动文字","blocks":[{"label":"操作方式"},{"label":"设置条件与区别","from":"此操作受"},{"from":"手机网页","role":"demo"}]},"5":{"title":"三种粘贴格式","navigationLabel":"粘贴与格式","blocks":[{},{"label":"保留源格式","from":"“保留源格式”"},{"label":"合并格式","from":"“合并格式”"},{"label":"只保留文本","from":"“只保留文本”"},{"label":"Word2016快捷键","from":"Word2016"}]},"6":{"title":"Office剪贴板","navigationLabel":"Office剪贴板","blocks":[{"label":"入口与用途"},{"label":"容量限制","from":"继续收集"},{"label":"与Windows剪贴板区分","from":"它与Windows"},{"label":"重复粘贴与保存","from":"普通粘贴"}]}},"fieldPresentation":{"boundary":{"blocks":[{},{"from":"选区和键盘","role":"demo"}]},"trigger":{"blocks":[{},{"from":"网页演示","role":"demo"}]}}},{"q":9,"chapter":3,"section":"3.2","type":"单选","topic":"查找替换","title":"查找替换可批量处理文本、特殊字符与格式","trigger":"真题从删除空段、段落对齐和批量清除字符格式考查查找替换。","conclusion":"查找内容决定“找谁”，替换文字和替换格式决定“改成什么”。同样文字替换回去并指定常规字形，可以只改变匹配文字的字形。","points":["指定文字恢复常规：按Ctrl+H，在“查找内容”和“替换为”都输入目标文字；将光标放到“替换为”，再选更多→格式→字体→常规。","核对两个文本框下方的格式摘要。查找一侧残留的字体、样式等条件会缩小匹配范围；用“不限定格式”清除不需要的条件，再设置本次条件。","只替换格式时，可让查找与替换文本框留空，分别设置查找格式和目标格式；不要将“替换为空”与“留空但指定替换格式”混为一谈。","清理连续空段时，在未启用“使用通配符”的条件下，可把^p^p替换为^p。若有更多连续空段，需重复处理；若段内还有空格或制表符，则不等于连续两个段落标记。","查找替换可改变匹配内容的字符或段落格式，也可匹配样式，但不能代替在样式库中修改样式定义。嵌入型图片跟随所在段落对齐，调整图片所在段落可使其居中。 “格式”菜单还可指定制表位等条件；查找对象是具有该格式的内容，仍需检查实际命中，不能把制表位条件与查找制表符字符混同。","“常规”同时取消加粗和倾斜；题目只要求取消某一种效果时，应核对是否需要保留其他效果。先检查匹配和替换范围，再执行全部替换。","普通改词：Ctrl+H→查找内容输入旧词→替换为输入新词→先用“查找下一处”和“替换”核对一处，再决定是否“全部替换”。仅把旧词替换为空且未指定替换格式，是删除匹配文本；单击清空查找框本身不会删除正文。","按Ctrl+F打开导航窗格，可查看标题、页面缩略图和搜索结果；点击结果跳到对应内容。复杂条件用开始→查找下拉菜单→高级查找，展开“更多”；按当前选区还是全文、向上还是向下查找，应看范围与提示，避免处理完选区后又无意继续到整篇。","“区分大小写”“全字匹配”、区分全半角以及忽略空格/标点等条件会改变匹配集合。比如只想改英文单词cat，不想改到catalog，应核对全字匹配；中文词边界、文档语言和版本选项会影响结果，先检查实际命中。 高级查找还可按前缀、后缀限制词的匹配，例如只匹配以指定串开头或结尾的词；是否可同时使用其他选项应以对话框可用状态为准。","Word只有启用“使用通配符”才按相应模式匹配；?代表单个字符，*可匹配一串字符，贪多的模式可能跨过本想保留的文本。它与Windows文件名搜索、Excel通配符不能整套照搬；本节不要求把所有内容套进一个复杂表达式。","查找结构标记时，优先从“特殊格式”菜单插入代码。在未启用通配符的查找中，^p是段落标记、^l是手动换行、^t是制表符、^m是手动分页符；自动换行与自动分页不是可同样删除的手动标记。开启通配符后可用的代码与查找/替换框位置不同，不把未开通配符的^p规则直接照搬。删除结构标记可能合并段落或改变排版，先逐处核对。"],"boundary":"相同文字换回去而未设置替换格式，不保证去掉原有加粗；格式条件放错一侧，会改变查找范围或替换结果。","id":"y2025q48","sources":[{"year":2024,"q":9,"type":"单选"},{"year":2025,"q":48,"type":"操作"}],"keys":["2024-9","2025-48"],"comparison":{"headers":["目标","查找设置","替换设置"],"rows":[["改文字","输入原词","输入新词"],["删除指定文字","输入原词","留空且不指定替换格式"],["指定文字恢复常规","输入目标词","相同词＋字形常规"],["只改格式","文本留空＋原格式","文本留空＋目标格式"]]},"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"替换匹配格式不等于修改样式定义；要让以后同级标题也继承规则，应改样式。"},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"清理连续空段前先认清段落标记与手动换行，避免替换错结构。"},{"id":"y2024q57","label":"用-*通配符批量删除连字符及其后缀","reason":"Excel和Word的通配符入口及语法不同，跨软件操作不能照搬勾选步骤。"}],"pointGroups":[{"title":"先定位匹配，再完成普通替换","indices":[7,8,6]},{"title":"按字形或格式批量处理","indices":[0,1,2,5,4]},{"title":"识别特殊标记与通配条件","indices":[3,9,10]}],"searchAliases":["查找下一处","全字匹配","区分大小写","使用通配符","^p","^l","^t","^m","删除空段"]},{"q":55,"chapter":3,"section":"3.2","type":"操作","topic":"校对标记","title":"校对波浪线提示可能的问题，不属于打印正文","trigger":"题目解释Word正文下方红色、绿色波浪线为何不出现在打印稿。","conclusion":"拼写、语法检查的波浪线是编辑提示，不是文档下划线，正常打印正文时不会把这些提示线印出来。","points":["红色波浪线通常提示可能的拼写问题；语法等提示颜色会随版本和校对组件变化，应根据校对建议判断，不能只背颜色。","右击标记可查看建议、忽略提示；已确认正确的专有词可加入词典。提示是待核查线索，不代表原文一定错误。","审阅→拼写和语法，或按F7启动检查；大量误报时先核对所选文字的校对语言。","自动更正会按设置把输入中的特定内容替换为预设结果，可在文件→选项→校对→自动更正选项中检查。它与“只画波浪线提示可能错误”不同；发现自动替换不合本意时撤销并核对规则，不因软件已替换就认定原文一定错。","字数统计：审阅→字数统计，或单击状态栏字数；Ctrl+Shift+G可打开统计对话框。先选中文字可查看选区统计，不选择时查看文档统计；字数、字符数（计空格/不计空格）、段落数、行数、页数不是同一个指标。需要计入文本框、脚注和尾注时核对相应选项；行数和页数会随排版改变。 例如computer是一个英文单词，却含8个字母；中文字符、非中文单词与字符数不能机械互换，混合文本按统计窗口的具体项目和范围判断。"],"boundary":"字体设置中的单下划线、双下划线属于正文格式，会打印；隐藏校对提示也不等于改正原文。","id":"y2023q55","sources":[{"year":2023,"q":55,"type":"操作"}],"keys":["2023-55"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"正文下划线属于字符格式会打印，校对波浪线只提示可能的问题。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"隐藏校对提示与隐藏修订都只影响查看；原文是否改正或修订是否处理需另外判断。"}],"pointGroups":[{"title":"提示与实际校对","indices":[0,1,2]},{"title":"自动更正与字数统计","indices":[3,4]}],"searchAliases":["自动更正","字数统计","Ctrl+Shift+G","F7","拼写","语法"],"pointPresentation":{"3":{"title":"自动更正","navigationLabel":"自动更正"},"4":{"title":"字数统计","navigationLabel":"字数统计","blocks":[{"label":"打开统计窗口"},{"label":"先确定统计范围","from":"先选中文字"},{"label":"分清统计指标","from":"字数、字符数"},{"label":"附加内容与排版条件","from":"需要计入"},{"label":"例子：单词与字符不同","from":" 例如computer"}]}}},{"q":6,"chapter":3,"section":"3.2","type":"单选","topic":"文档视图","title":"Word视图、标题结构与导航窗格","trigger":"真题从视图用途、标题重组和导航窗格无标题的故障现象考查长文档结构。","conclusion":"先给正文标题建立层级，再用大纲视图组织内容、导航窗格定位标题，最后用打印布局核对实际页面。只放大、加粗文字不会建立标题结构。","points":["建立层级：给一级、二级标题分别应用“标题1”“标题2”；自定义标题可设置相应大纲级别。不要把整篇标题都设为同一级。","导航窗格：视图→导航窗格→标题。单击标题定位；在标题列表中拖动标题可连同所属内容调整顺序。表格、文本框、页眉和页脚中的标题不在这个列表中。","自动目录：引用→目录。默认自动目录依据标题层级生成；自定义目录还可配置样式、大纲级别或目录条目。","目录更新：只改变分页时可更新页码；新增、删除或改名标题后应更新整个目录。直接编辑目录显示文字不能替代修改正文标题。","草稿视图侧重文字，不显示图片、页眉页脚；桌面Word的Web版式仍可编辑文字和查看图片，不按纸张分页。不要把Web版式误当成只读网页。","误删文字后按Ctrl+Z撤消；撤消后要恢复该动作可按Ctrl+Y。没有待恢复动作时，Ctrl+Y或F4可用于重复受支持的上一操作，效果取决于当前状态。","教学示例：删除一段→Ctrl+Z恢复该段→Ctrl+Y再次删除。保存文件等动作不一定能够撤消，不能把快捷键当作任何操作的通用回退。","要逐段核对两份文档，先打开两文件→视图→并排查看；开启“同步滚动”可一起翻动，关闭后可分别滚动。并排查看只改变显示方式，不自动合并两份内容。","先认识样式：样式是带名称的一组格式规则。准备把一段文字作为标题时，选中完整的标题段落，在开始→样式中选择“标题1”或“标题2”；样式库未显示需要的项目时可展开“更多”。应用后核对样式名称，再看外观；只把文字加粗、放大到相同样子，不等于已经应用同一样式。下面再用标题级别建立结构，并检查导航和目录。"],"boundary":"导航窗格、正文标题和自动目录是相关的三个对象；某处看起来像标题，不能保证它会被导航或目录收录。","id":"merged-5","sources":[{"year":2020,"q":6,"type":"单选"},{"year":2023,"q":8,"type":"单选"},{"year":2023,"q":66,"type":"分析"},{"year":2026,"q":27,"type":"多选"},{"year":2021,"q":41,"type":"操作","page":6},{"year":2021,"q":45,"type":"操作","page":7},{"year":2021,"q":46,"type":"操作","page":7}],"keys":["2020-6","2023-8","2023-66","2026-27","2021-41","2021-45","2021-46"],"comparison":{"headers":["视图","主要用途","查看页面效果"],"rows":[["打印布局","编辑文档并检查分页、页眉页脚","适合核对打印版式"],["大纲视图","按标题级别升降级、重排内容","重在文档结构"],["草稿视图","集中编辑正文","不显示图片、页眉页脚和完整页面版式"],["Web版式","按网页连续显示，仍可编辑","不按纸张正常分页"],["阅读模式","以屏幕阅读为主","阅读显示不改变文档格式"]]},"searchAliases":["目录不显示标题","导航没有标题","标题不进目录","目录页码不对"],"related":[{"id":"y2023q52","label":"继续学习样式的创建、修改与例外","reason":"本卡已能完成标题样式应用与导航目录；需要统一修改同级标题时，再学习样式定义、直接格式例外和更新范围。"},{"id":"y2022q72","label":"Word标题层级决定导入PowerPoint后的幻灯片结构","reason":"同一套Word标题层级还决定从大纲导入PowerPoint时的幻灯片和正文归属。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"普通目录依据标题，图表目录依据题注，可对照理解自动目录各自的结构来源。"}],"pointGroups":[{"title":"按任务选择视图与并排查看","indices":[4,7]},{"title":"撤销、恢复与重复操作","indices":[5,6]},{"title":"认识样式，建立标题层级并导航","indices":[8,0,1]},{"title":"生成与更新自动目录","indices":[2,3]}],"pointPresentation":{"8":{"title":"先认识并应用标题样式","navigationLabel":"认识标题样式"}}},{"q":10,"target":null,"chapter":3,"section":"3.2","topic":"按样式选择","title":"按同一格式或样式批量选中文本","conclusion":"要删除应用指定样式的标题文字，应先选中全部目标实例，再删除内容；清除格式、删除样式定义和删除文字分别处理。","points":["按样式选择：开始→样式，打开目标样式的菜单，选择所有使用该样式的实例，再核对选区。","按外观选择：先选中一个目标，再用开始→选择→选择格式相似的文本。相同外观可能来自不同样式，不能仅凭选中结果认定它们都属于“标题1”。","执行删除前确认选择的是全部目标文字；要调整格式时保留文字，不按Delete。","按Delete删除的是选区内容；开始→字体→清除所有格式保留文字，但要重新检查样式身份与标题结构。从样式库移除一个入口，通常只是让快捷样式库不再显示它，该样式仍可存在于样式窗格中。移除入口不等于删除定义，更不等于删掉使用它的所有文字；想让文字改用别的样式，应明确应用目标样式。","需要删除自定义样式时，先在当前文档的样式窗格定位它，核对使用它的文本，给需保留的内容应用合适的替代样式，再查看该样式菜单提供的删除操作与确认提示。删除定义不是按Delete删除文字，也不是从样式库移除快捷入口。课堂将删除后的效果简写为“恢复默认”；在用样式删除后的具体回退、直接格式保留及内置样式菜单限制尚待Word2016核验，不能承诺所有文字一定变成同一种外观。","2022年第10题B项写“查找内容为标题1”，须区分字面查找文字和通过查找格式指定样式：前者找的是这几个字，不能因此选中所有应用标题1的段落。题面没有把格式条件写清，配套未署名答案不能消除这处歧义。遇到类似题，逐项核对选区对象、匹配条件以及最后执行的是删除内容还是清除格式；原本按样式选择的规则继续适用。"],"boundary":"不要把“删除样式”当作删除所有标题内容。","type":"单选","trigger":"从按样式选择的判断与应用整理。","id":"y2022q10","sources":[{"year":2022,"q":10,"type":"单选"}],"keys":["2022-10"],"comparison":{"headers":["做法","文字内容","格式或样式"],"rows":[["选中后按Delete","删除所选内容","不是修改样式定义"],["清除格式","保留内容","移除相应格式"],["修改“标题1”样式","保留内容","更新使用该样式的格式规则"]]},"related":[{"id":"y2023q52","label":"从选择样式实例进到修改样式规则","reason":"按同一样式选中文字后，可以删除这些内容；若目标是保留文字并统一格式，继续学习如何修改样式定义和检查局部例外。"},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"查找替换也能按格式匹配，但要核对查找条件，防止相同外观掩盖不同样式。"},{"id":"y2021q56","label":"样式和模板分别在哪个文件保存","reason":"删除或修改定义前，确认操作对象是当前文档还是模板，避免混淆影响范围。"}],"pointPresentation":{"0":{"title":"按样式身份选择"},"1":{"title":"按外观选择的边界"},"2":{"title":"删除前核对目标文字"},"3":{"title":"删文字、清格式与移出样式库","navigationLabel":"删文字、清格式与移出样式库"},"4":{"title":"删除自定义样式前先安排替代样式","navigationLabel":"删除自定义样式前先安排替代样式"},"5":{"title":"真题中的“标题1”是名称还是查找文字","navigationLabel":"真题中的“标题1”是名称还是查找文字"}},"pointGroups":[{"title":"先选择正确对象","indices":[0,1,2]},{"title":"区分删除和格式操作","indices":[3,4]},{"title":"读题时核对匹配条件","indices":[5]}],"searchAliases":["删除样式","清除所有格式","移出样式库","查找标题1"]},{"q":42,"chapter":3,"section":"3.3","type":"操作","topic":"字符与段落格式","title":"显示、字符格式与段落对齐要分清","trigger":"真题从字号、上标、字形、下划线、显示缩放和段落对齐反复考查格式边界。","conclusion":"先判断改变的对象：字符格式管字，段落格式管整段排布，显示比例管屏幕查看。三者都可能让文字“看起来变了”，但对打印的影响不同。","points":["上标抬高并缩小所选字符，下标降低并缩小所选字符。Word快捷键：上标Ctrl+Shift+=，下标Ctrl+=；它们改变格式，不是把内容改成另一种Unicode字符。","字体对话框可设置字形、字号、单/双下划线、删除线和着重号；校对波浪线只是提示，不属于这些打印格式。","字体颜色改变字本身；文本突出显示颜色像荧光笔标记字符背景；段落底纹按段落范围着色，页面颜色改变页面背景。","两端对齐通常不拉伸自然结束的末行；分散对齐可让末行也分散到左右边界。判断时检查最后一行，并区分自然段结束与手动换行。","标题要求居中且无首行或悬挂偏移：设置段落居中，并把特殊格式设为“无”；若已有左右缩进，还需核对它们是否符合要求。","全角１２３与半角123是不同字符。选中文字后可在中文Word的开始→字体→更改大小写→半角中转换；格式刷只复制格式，不做这种字符转换。","设置字符格式前，先选中要处理的文字；未选择时设置字体通常影响插入点后新输入的内容，不能当成已修改全文。入口是开始→字体，更多项目用字体组对话框启动器或Ctrl+D；选中文字后也可使用浮动工具栏。","字号常以磅（pt）表示，1磅为1/72英寸，磅值越大通常字越大。中文字号名称中，五号比小五大，四号比五号大；“号”的数字不能按磅值的大小方向去比较。字体不同，同字号字面观感仍可不同。屏幕显示缩放不改实际字号，打印题应检查字体设置。","加粗Ctrl+B、倾斜Ctrl+I、下划线Ctrl+U可分别切换；下划线在文字下方，删除线穿过文字，着重号是强调标记，不是校对波浪线。需要双下划线、特定颜色或字形“常规”时进入字体对话框，不把同时清除粗体和斜体当成只取消一种效果。","字符间距在字体对话框→高级中设置。“间距”的加宽/紧缩改变字符之间的距离；“缩放”按比例拉宽或压窄字符；“位置”的提升/降低改变相对基线的位置。三者与字号、行距以及中文与数字自动间距不同，不能把“加宽”解释成缩小间距。","复制格式：选取有目标格式的文字→开始→剪贴板→格式刷→刷过目标文字。单击格式刷通常使用一次，双击可连续刷多处，Esc退出。若同时要复制段落格式，源选区应包含段落标记；只选几个字不能保证取得整段设置。格式刷复制格式，不复制文字内容或把半角数字转换成全角。","清除格式：选中目标→开始→字体→清除所有格式，文字内容仍保留；要精确取消一项，直接取消对应按钮更合适。直接格式会与样式叠加，不能把清除格式当作删除文字或修改样式定义。","段落对齐先确定作用段落，再用开始→段落选择左对齐、居中、右对齐、两端对齐或分散对齐；常用快捷键为Ctrl+L/E/R/J，分散对齐为Ctrl+Shift+J。对齐在段落的左右缩进边界之间计算；“默认两端对齐/默认单倍行距”取决于模板、样式和已改设置，不能当成每份Word2016文档都必然如此。","普通文字的边框和底纹也要确认范围：选中文字→开始→段落→边框下拉→边框和底纹，核对“应用于”文字还是段落；底纹页设置填充。文字边框/底纹围绕相应文字区域，段落边框/底纹按整段区域处理。字体颜色、突出显示、文字底纹和页面背景并非同一个设置，清除其中一种不保证其他颜色也消失。"],"boundary":"要求“打印时字更大”应改字号，要求“屏幕上看得更大”可改缩放；先确认目标，不能用同一个按钮替代。","id":"merged-7","sources":[{"year":2020,"q":42,"type":"操作"},{"year":2023,"q":51,"type":"操作"},{"year":2024,"q":52,"type":"操作"},{"year":2025,"q":29,"type":"多选"},{"year":2025,"q":46,"type":"操作"},{"year":2026,"q":46,"type":"操作"},{"year":2022,"q":53,"type":"操作"},{"year":2021,"q":42,"type":"操作","page":6},{"year":2021,"q":43,"type":"操作","page":6}],"keys":["2020-42","2023-51","2024-52","2025-29","2025-46","2026-46","2022-53","2021-42","2021-43"],"comparison":{"headers":["层级","典型项目","影响打印"],"rows":[["字符格式","字体、字号、字形、上下标、下划线","会改变字的排版或外观"],["段落格式","对齐、缩进、段前段后、行距","会改变段落排布"],["显示比例","100%改为150%","不改变文档打印尺寸"]]},"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"段落末行的对齐效果取决于段落结构，Enter与手动换行不能混用。"},{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"居中后仍有偏移时，应继续检查首行、悬挂和左右缩进标记。"},{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"全角半角转换改变字符身份，不能把它当成只改变字号或字体的操作。"}],"pointGroups":[{"title":"选定对象、字体与字号","indices":[6,7,0,1]},{"title":"字形、颜色和字符间距","indices":[8,2,9,13]},{"title":"复制或清除格式","indices":[10,11,5]},{"title":"段落对齐与末行判断","indices":[12,3,4]}],"searchAliases":["字体","字号","磅","格式刷","Ctrl+D","字符缩放","加宽","紧缩","删除线","着重号","清除格式","分散对齐"]},{"q":43,"chapter":3,"section":"3.3","type":"操作","topic":"段落缩进与换行","title":"首行缩进属于段落，手动换行不会新建段落","trigger":"真题从手工空格和手动换行符考查首行缩进的作用范围。","conclusion":"首行缩进作用于每个段落的第一行。Enter建立新段落，Shift+Enter只在原段落内换行，自动换行也不会重算一个新段落的首行。","points":["设置2字符首行缩进：选中正文段落→开始→段落对话框→缩进和间距→特殊格式“首行缩进”→度量值“2字符”。","在开始→段落中开启“显示/隐藏编辑标记”：段落标记是¶，手动换行标记是弯箭头。以标记判断结构，不能只看视觉上是否另起一行。","首行缩进只改变第一行；左缩进改变整段的左侧位置；悬挂缩进使首行之外的各行相对缩进。","不要靠段首空格凑2字符。空格属于内容，会受字体与字号影响，也不能给每个新段落建立稳定的缩进规则。","要让后文从下一页开始，可用Ctrl+Enter插入手动分页符；它与Enter新段落、Shift+Enter同段换行、分节符建立新节不同。不应连续敲Enter凑出下一页，因为前文变化后这些空段会重新占位置。","段落对话框→换行和分页中：“孤行控制”用于避免段首或段尾单独一行留在页边；“与下段同页”尽量让本段与下一段的开头同页，常用于标题；“段中不分页”尽量让本段各行同页；“段前分页”使本段从新页开始。这些控制分页，不负责把三行文字横向挤成两行；连续设置涉及的内容超过一页时仍需分页，超长段落与版面约束应检查实际结果。"],"boundary":"下一行是否执行首行缩进，取决于它是否属于新段落；按Enter后的新段还受“后续段落样式”等样式规则影响。","id":"y2020q43","sources":[{"year":2020,"q":43,"type":"操作"},{"year":2024,"q":51,"type":"操作"}],"keys":["2020-43","2024-51"],"comparison":{"headers":["换行方式","是否新段落","首行缩进"],"rows":[["文字到行末自动换行","否","仍按原段落的非首行排布"],["Shift+Enter","否","不会因换行重新成为首行"],["Enter","是","按新段落的格式规则执行"]]},"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"首行、悬挂和整段左缩进可用标尺分别调节，先按受影响的行确定标记。"},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"替换空段要识别真正的段落标记；手动换行与含空格的空行不等于连续空段。"}],"workedExamples":[{"year":2020,"q":43,"questionSummary":"只让每个正文段落第一行缩进两个字符。","reasoning":["目标只改变每段第一行，相应属性是首行缩进。","左缩进会移动整段，悬挂缩进主要移动除第一行外的后续行。","逐段敲空格只是字符内容，不是稳定的段落格式。"],"pitfall":"把“从左边空两格”误解为整段左缩进，或用空格模拟排版。","transfer":"先选中需要设置的段落，再设置特殊格式首行；按Enter形成新段落，手动换行仍在原段落内。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"本轮已核对原卷PDF第6页第43题及第5页图3；配套参考答案无可确认的官方发布依据。公开链接为转录入口。","historicalVersionNote":"该年公开题面沿用Windows 7/Office 2010。此处保留原题语境；站内操作入口须按Windows 10/Office 2016另行说明。"}],"pointGroups":[{"title":"先辨认段落，再设置首行缩进","indices":[1,2,0,3]},{"title":"另起页与段落分页控制","indices":[4,5]}]},{"q":24,"target":null,"chapter":3,"section":"3.3","topic":"标尺与缩进","title":"标尺四个缩进标记控制不同的行","conclusion":"拖标尺前先确定要移动第一行、其余行、整段左边界还是右边界。左下方方块会带着首行和悬挂标记一起移动，保留它们的相对距离。","points":["先选中需要调整的段落，在视图中显示标尺，再拖相应标记；否则可能只修改光标所在段落。","首行比其余行更靠右表现为首行缩进；首行比其余行更靠左表现为悬挂缩进。不要把三角形朝向直接当作“向左/向右缩进”。","拖页边距交界改变页面可排版区域；拖缩进标记改变段落相对该区域的位置。行距、段前和段后间距不由水平标尺这些标记控制。","需要准确数值时，选中段落→开始→段落对话框→缩进和间距，分别设置左、右缩进及特殊格式。先看页边距，再看段落缩进；缩进通常以正文可排版区域为参照，不是从纸张物理边缘量起。","例如左页边距3厘米、段落左缩进1厘米且无首行/悬挂时，各行起点距纸张左边缘4厘米；若再设首行缩进0.5厘米，第一行起点为4.5厘米，其余行仍为4厘米。悬挂缩进应分别检查第一行和后续行，不能只看最靠左的一行就断言左缩进为0。"],"boundary":"先分清“第一行”“其余行”“整段”，不要把首行缩进和悬挂缩进方向记反。","type":"多选","trigger":"从标尺与缩进的判断与应用整理。","id":"y2022q24","sources":[{"year":2022,"q":24,"type":"多选"}],"keys":["2022-24"],"comparison":{"headers":["标记","拖动后改变","其余部分"],"rows":[["左上三角","第一行的起点","其余行起点保留"],["左下三角","除首行外各行的起点","首行起点保留"],["左下方块","整个段落的左侧位置","首行与其余行的差值保留"],["右端三角","段落右边界","不等于页面右页边距"]]},"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"观察第一行和其余行的位置，才能区分首行缩进与悬挂缩进。"},{"id":"merged-8","label":"项目符号、编号与多级列表","reason":"多级列表的编号位置、文本缩进与制表位要协调，不能只拖一个标记或堆空格。"}],"pointGroups":[{"title":"标尺对应哪部分","indices":[0,1,2]},{"title":"精确设置与距离判断","indices":[3,4]}]},{"id":"syllabus-word-paragraph-spacing","chapter":3,"section":"3.3","origin":"syllabus","type":"知识补充","topic":"段落间距与行距","title":"段前段后与行距：分清段间和段内距离","conclusion":"段前、段后控制段落外的留白，行距控制同一段内各行的排布。固定值限制行高，最小值允许内容需要时增高。","points":["只处理一个段落时，将插入点放在该段内即可设置段落格式；处理多个段落应选中涉及的段落，处理正文全部段落先核对是否要Ctrl+A。用开始→段落对话框→缩进和间距，或布局中的段前/段后输入框设置；字符选区很短，也可能改变它所在整段的段落格式。","段前在段落前增加留白，段后在段落后增加留白；它们不是空格，也不增加空段。按题目单位输入，例如段后6磅或段前0.5行，不把“6磅”写成“6行”。相邻段落的实际留白还受间距合并、同样式段落不添加间距和页首位置等规则影响，不能只把两个框的数字相加当成实测结果。","单倍行距根据当前字体与内容安排行高；1.5倍、2倍和多倍按单倍基准调整。“1.5倍行距”不等于固定18磅，也不是增加1.5行空段。相同字体和内容下增大行距主要拉开纵向距离，不负责压缩每行的字符。","“最小值”设置行高下限，较大字体或嵌入型图片需要更多空间时允许增高；“固定值”使用指定磅值，过小可能裁切大字、公式或嵌入型图片。固定值越小不代表内容越完整，也不要把问题误判成图片文件损坏。","例如题目要求正文1.5倍行距、段后6磅：先选正文各段→段落对话框→行距选1.5倍→段后输入6磅→确定，再核对段内各行和两个段落之间的变化。标题不在任务范围时应排除标题；改行距不能代替设置段后。","如果设置看似没有生效，先核对选区、单位、所选行距类型，再看“如果定义了文档网格，则对齐到网格”等选项、样式和内容对象。默认格式来自模板与样式，不能把课堂示例的初始值当成所有文档统一默认值。"],"boundary":"行距、字号、字符间距、段前段后和页面留白属于不同参数。要把文字多占一行的原因找准，仍须同时检查行宽、字体及横向间距。","sources":[],"keys":[],"searchAliases":["段前","段后","段落间距","单倍行距","1.5倍行距","多倍行距","固定值","最小值","文档网格"],"trigger":"按2026年考试要求与已核查课堂范围补充；操作以Windows桌面Word2016为基线，具体来源见参考资料。网页演示不等于真实Word实测。","pointGroups":[{"title":"作用范围和段落外留白","indices":[0,1]},{"title":"段内行距的类型与限制","indices":[2,3]},{"title":"按要求设置并排错","indices":[4,5]}],"related":[{"id":"y2024q66","label":"固定行距裁切图片","reason":"用嵌入型对象核对固定值与最小值的边界。"},{"id":"y2020q43","label":"换行与分页控制","reason":"区分行距、段落结构与分页设置。"}],"pointPresentation":{"0":{"title":"设置对象与入口","navigationLabel":"设置对象与入口","blocks":[{"label":"处理哪些段落"},{"label":"操作入口","from":"用开始"},{"label":"作用范围提醒","from":"字符选区"}]},"1":{"title":"段前与段后","navigationLabel":"段前与段后","blocks":[{"label":"控制段落外留白"},{"label":"核对输入单位","from":"按题目单位"},{"label":"相邻段落的条件","from":"相邻段落"}]},"2":{"title":"单倍与倍数行距","navigationLabel":"倍数行距"},"3":{"title":"最小值与固定值","navigationLabel":"最小值与固定值","blocks":[{"label":"最小值"},{"label":"固定值","from":"“固定值”"},{"label":"裁切问题","from":"固定值越小"}]},"4":{"title":"设置1.5倍行距、段后6磅","navigationLabel":"设置步骤与核对","blocks":[{"label":"题目要求"},{"label":"设置步骤","from":"先选正文","steps":["先选正文","段落对话框","行距选","段后输入","确定"]},{"label":"核对结果","from":"再核对"},{"label":"范围与易错","from":"标题不在"}]},"5":{"title":"设置未生效时的检查","navigationLabel":"设置没有生效","blocks":[{"label":"依次排查"},{"label":"默认值的来源","from":"默认格式"}]}},"fieldPresentation":{"trigger":{"blocks":[{},{"from":"网页演示","role":"demo"}]}}},{"q":47,"chapter":3,"section":"3.3","type":"操作","topic":"中文版式","title":"中文与数字、中文与西文的自动间距分别控制","trigger":"题目要求解释相同文字为何多占一行并选择压缩方法。","conclusion":"中文与数字、中文与西文是两个独立选项。文段含“10亿年”等数字时，应检查“自动调整中文与数字的间距”。","points":["入口：开始→段落对话框启动器→中文版式→字符间距。","取消中文与数字间距，影响汉字和数字交界处；中文与西文选项影响汉字与拉丁字母交界处。","自动间距不同于手动输入的空格；关闭自动间距不会删除真实空格，也不会改字号。","行数是否减少还取决于字体、字号和行宽，不能保证每个文段都恰好从三行变两行。","1.5倍行距主要改变行与行的纵向距离；孤行控制调整跨页时单行的分布。它们都不直接缩小汉字与数字的横向间距，不能用“行距一变，原文行数一定只会增多或一定会减少”解释题目。是否换行仍要结合字符宽度和可用行宽。"],"boundary":"为挤进行数而任意缩放字符会损害可读性，应先查明真正的版式来源。","id":"y2026q47","sources":[{"year":2026,"q":47,"type":"操作"}],"keys":["2026-47"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"自动字符间距、字形字号与段落对齐作用不同，调整版面前应先确认要改变哪一层。"},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"真实空格属于文本内容，缩进和自动间距属于排版规则，不能用删除空格替代所有调整。"},{"id":"syllabus-word-paragraph-spacing","label":"纵向距离不等于横向字符间距","reason":"行距与段间距各有作用范围。"}],"pointGroups":[{"title":"独立控制两类自动间距","indices":[0,1,2]},{"title":"行数变化的条件与排错","indices":[3,4]}]},{"q":66,"chapter":3,"section":"3.3","type":"分析","topic":"行距与图片","title":"固定行距过小会裁切嵌入型图片","trigger":"题目描述按Enter后粘贴图片，图片为嵌入型却只能显示一部分。","conclusion":"嵌入型图片占据文本行；若段落设置了小于图片高度的固定值行距，行框会裁切图片。","points":["改为单倍、多倍或“最小值”行距可让行高随对象增大。","若必须用固定值，应把磅值调到足以容纳图片。","图片环绕方式不是唯一原因，应先检查段落行距。"],"boundary":"“固定值”与“最小值”不同：固定值锁死行高，最小值允许内容更高时自动扩展。","id":"y2024q66","sources":[{"year":2024,"q":66,"type":"分析"}],"keys":["2024-66"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按文本行排布，因此可能被固定行高裁切；浮动图片采用另一套位置规则。"},{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"图像被裁切不一定要缩小原图，应先分辨是行距限制还是主动裁剪。"},{"id":"syllabus-word-paragraph-spacing","label":"段前段后与行距","reason":"先辨认参数再修复行高。"}]},{"q":4,"chapter":3,"section":"3.3","type":"单选","topic":"多级列表","title":"项目符号、编号与多级列表","trigger":"四道题从入口、层级调整和缩进排错考查Word列表功能。","conclusion":"项目符号适合无序内容，编号适合有序内容；多级列表用编号位置、文本缩进和制表位共同控制层级版式。","points":["项目符号、编号和多级列表位于开始→段落。无先后关系用项目符号；顺序步骤用编号；章节层次用多级列表。","在列表项文本开头，Tab通常降一级、Shift+Tab通常升一级；行为还受自动调整缩进设置影响。也可在多级列表菜单中使用“更改列表级别”。","一级“1.”与二级“1.1”要建立真正层级。章节编号可先应用“标题1”“标题2”，再从多级列表库选择带标题样式的编号方案；只增大左缩进或只改编号字体，都不会替代标题层级。","编号错位时分别检查编号对齐位置、文本缩进位置和编号后的制表位；不要用连续空格手工补齐。","自定义项目符号可使用符号或图片；符号可设置字体、颜色。编号可设置样式和起始值，不必逐项手改数字。 编号也可在定义新编号格式中设置字体及颜色；不能把可自定义图片项目符号理解为自动编号数字也可直接用图片替换。","列表作用于段落：选中各项段落后应用项目符号或编号；在列表项末尾按Enter通常延续下一项，在空列表项再次Enter通常结束列表。Shift+Enter仅在同一项内换行。手动输入“1.”或用插入→符号插入编号字符，不能保证建立自动编号；是否自动转为列表还取决于自动更正设置。","编号与文字间空隙过大时，先分清编号起点和正文起点。题设编号位置正确而正文过远，应减小该级的文本缩进；若“编号之后”选择制表符，还需使制表位与预期文字起点协调。改成空格或无时空隙机制不同，不能断言只改编号位置永远不影响间距，也不能只靠改变字体解决缩进问题。"],"boundary":"不要用空格手工对齐多级编号；普通正文中的Tab可能只是插入制表符。","version":"已转换为Word 2016","id":"merged-8","sources":[{"year":2020,"q":4,"type":"单选"},{"year":2026,"q":56,"type":"分析"},{"year":2026,"q":57,"type":"分析"},{"year":2026,"q":58,"type":"分析"}],"keys":["2020-4","2026-56","2026-57","2026-58"],"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"编号错位常要调整文本缩进和制表位，先认清首行、悬挂与整段缩进。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"章节多级编号应与标题层级协调，单纯增大缩进不会建立可导航的标题结构。"}],"pointGroups":[{"title":"选择列表类型与段落范围","indices":[0,5]},{"title":"建立和调整真实级别","indices":[1,2]},{"title":"编号、文本与符号的区别","indices":[3,6,4]}]},{"q":61,"chapter":3,"section":"3.3","type":"综合","topic":"分节","title":"分页分节与页面设置：只改变目标范围","trigger":"先判断需要换页还是独立的页面格式，再确认设置影响整篇、当前节还是所选部分。","conclusion":"纸张方向按节设置。只让中间一页横向，要把该页内容单独分成一节，并确认横向仅应用于这一节。","points":["手动分节：在目标页内容前插入布局→分隔符→下一页分节符；在目标内容后再插入下一页分节符，使后文重新成为另一节。","把光标放在目标节，打开页面设置，设为横向并确认“应用于：本节”；再检查前后两节仍为纵向。","也可先选择需要横向的内容，在页面设置中选横向，并把“应用于”设为“所选文字”；Word会为不同方向建立所需分节边界。","节还可分别控制页边距、页眉页脚和页码设置；但页眉页脚是否沿用前节，要另外看链接状态。","页是排版后的一页；节是可独立设置页面格式的编辑单位。一节可以跨多页，一页也可因连续分节包含不同的节。只想让后文另起一页，用分页；需要不同方向、页边距或栏数等格式时，再考虑分节。","自动分页由Word根据纸张、页边距、正文及段落分页设置计算；不是可以直接选中删除的一条人工分页符。人工分页：把插入点放在要另起一页的文字之前，按Ctrl+Enter；也可用插入→页→分页，或布局→页面设置→分隔符→分页符。结果是后文从下一页开始，仍属于原节。","先用开始→段落→显示/隐藏编辑标记辨认“分页符”与“分节符（类型）”。删除人工分页符：把插入点放在该标记前，按Delete；后文按剩余内容重新排版，不保证一定少一页。若没有人工分页符却提前换页，应检查页面容量及段落的段前分页、与下段同页等设置，不能盲目删除正文。","布局→页面设置→分隔符的“分节符”下选择：下一页——新节从下一页开始，适合新章或单独横向的页面；连续——在当前页开始新节，常用于同页前后栏数不同；奇数页、偶数页——新节从后续相应奇偶页开始，适合章节按规定奇偶页起排，必要时会留下过渡空白页。选择的是新节的起始方式，不是给当前页设置奇偶页眉。","修改起始方式：定位要改变的节，打开布局→页面设置对话框→版式，在“节的起始位置”改选类型并确定；不要用再插一条分节符代替修改。删除分节符：先显示编辑标记，把光标放在分节符前按Delete。前后文本合为一节，采用原后节的格式，前面的方向、页边距等可能随之改变。删后立即核对前后版面；结果不符合目标时撤销，再调整正确的节或范围。","纸张大小决定版面尺寸，横向/纵向决定方向，上下左右页边距限定正文排版区域。布局→页面设置组可设置纸张大小、方向、页边距；精确值在页面设置对话框中核对。“页边距”选项卡还含装订线及其位置；“纸张”选项卡设置纸张大小，“版式”含节起始及首页/奇偶页选项。先按题目设置，再预览相邻页；页面设置可以在编辑过程中修改。","整篇文档：把本次设置应用到全文。 本节：只设置插入点所在的节，不能把它理解为“当前一页”。 所选文字：先选目标内容，再在对话框确认此范围，局部方向需由分节边界隔离。 插入点之后：从当前位置开始的后续范围，不能保证只改当前页。可选项随选区、已有节和当前对话框而变；每次确定前都要看实际的“应用于”，不能机械套用默认项。","减小页边距会扩大纸面上的正文区域，可能改变每页容纳的文字和总页数；它不等于把字号改小。显示比例只改变屏幕查看大小，不改保存和打印的版面。判断题目中的“文字大小”与“容纳多少内容”时，先区分这三个设置。"],"boundary":"如果只在目标页之前分节而没有隔离后文，横向可能继续影响后面的多页；操作后必须检查相邻页。","id":"y2020q61","sources":[{"year":2020,"q":61,"type":"综合"}],"keys":["2020-61"],"comparison":{"headers":["分隔方式","作用","范围辨析"],"rows":[["分页符","从新页继续同一节","不能单独隔离纸张方向"],["下一页分节符","从新页开始新节","可以划出节边界"],["连续分节符","在当前页开始新节","常用于同页分栏等设置"]]},"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"分节能隔离纸张方向，但页眉页脚是否继承还需单独检查链接状态。"},{"id":"y2020q44","label":"正文分栏会改变排版，页面并排只改变屏幕查看","reason":"局部分栏可使用连续分节，局部横向常用下一页分节；二者都需核对影响范围。"},{"id":"y2020q43","label":"换行、分段与段落分页设置","reason":"没有人工分页符仍换页时，继续检查段前分页、与下段同页等段落设置。"}],"searchAliases":["页与节","自动分页","人工分页符","奇数页分节符","偶数页分节符","纸张大小","页边距","应用于","页面布局"],"pointPresentation":{"0":{"title":"第一步：隔离目标内容","navigationLabel":"第一步：隔离目标内容","blocks":[{"label":"前后两个边界","steps":["手动分节：","在目标内容后"]}]},"1":{"title":"第二步：应用本节并检查前后"},"2":{"title":"替代操作：先选中文字"},"3":{"title":"相邻设置：页眉链接另管"},"4":{"title":"页与节：两个不同的范围","navigationLabel":"页与节：两个不同的范围"},"5":{"title":"自动分页与人工分页符","navigationLabel":"自动分页与人工分页符","blocks":[{"label":"自动分页"},{"from":"人工分页：","label":"插入步骤","steps":["人工分页：","也可用"]},{"from":"结果是","label":"结果"}]},"6":{"title":"显示标记与删除人工分页符","navigationLabel":"显示标记与删除人工分页符","blocks":[{"label":"先辨认对象"},{"from":"删除人工分页符：","label":"操作与结果"},{"from":"若没有","label":"仍然换页时"}]},"7":{"title":"四种分节方式及用途","navigationLabel":"四种分节方式及用途","blocks":[{"label":"入口与下一页"},{"from":"连续——","label":"连续"},{"from":"奇数页、偶数页——","label":"奇数页与偶数页"},{"from":"选择的是","label":"区别"}]},"8":{"title":"修改与删除分节符的影响","navigationLabel":"修改与删除分节符的影响","blocks":[{"label":"修改已有类型"},{"from":"删除分节符：","label":"删除步骤"},{"from":"前后文本","label":"删除结果与检查"}]},"9":{"title":"纸张、方向与页边距","navigationLabel":"纸张、方向与页边距","blocks":[{"label":"设置对象"},{"from":"布局→","label":"入口"},{"from":"“页边距”","label":"对话框中的位置"},{"from":"先按","label":"检查"}]},"10":{"title":"“应用于”决定改变哪一部分","navigationLabel":"“应用于”决定改变哪一部分","blocks":[{"label":"整篇文档"},{"from":"本节：","label":"本节"},{"from":"所选文字：","label":"所选文字"},{"from":"插入点之后：","label":"插入点之后"},{"from":"可选项","label":"确定前检查"}]},"11":{"title":"页边距不是字号或显示比例","navigationLabel":"页边距不是字号或显示比例"}},"pointGroups":[{"title":"先分清页、节与标记","indices":[4,5,6,7,8]},{"title":"页面设置先选对象与范围","indices":[9,10,11]},{"title":"完整操作：中间一页横向，前后保持纵向","indices":[0,1,2,3]}]},{"q":44,"chapter":3,"section":"3.3","type":"操作","topic":"分栏与页面查看","title":"正文分栏会改变排版，页面并排只改变屏幕查看","trigger":"真题从两栏排版和多页并排阅读考查两个容易混淆的功能。","conclusion":"选中文本后用“布局→栏→两栏”建立报刊式文本流；多页/并排查看只改变屏幕显示，不改变打印版式。","points":["只给一段正文分栏：先选中目标文字，再用布局→栏→两栏；“更多栏”中核对“应用于”范围。Word可用连续分节符隔离所选部分。","文字通常按左栏从上向下，再流向右栏；要提前转到下一栏可插入分栏符，不必用大量空行顶过去。","更多栏可设置栏数、栏宽、间距和分隔线；不等栏宽需要取消等宽设置后分别调整。","分栏会改变正文排版和打印结果；视图中的多页显示、并排查看只改变屏幕查看方式。","入口是布局→页面设置组→栏→更多栏；旧Word2010题面可能写“页面布局”，这里不是开始→段落对话框，也不是“分列”。按要求选栏数；等宽时用“栏宽相等”，不等宽时取消该项并分别设置宽度和间距。分隔线控制栏间竖线，不负责强制换栏。确定前检查应用范围，取消则不应用本次草稿。","全文需要同样分栏时在“应用于”确认整篇文档；已有多个节时，不能把当前节的设置误当成全文。只改中间正文时先选择目标内容并核对“所选文字”，或先用连续分节符隔离正文，再应用于本节。“插入点之后”用于从当前位置开始的后文；若后面的结束语仍需通栏，还要在正文结束处隔离后文。","前提是需要控制多栏文字的换栏位置。在要移入下一栏的文字前放置插入点，用布局→页面设置→分隔符→分栏符，或Ctrl+Shift+Enter。后续文字从下一栏开始；打开显示/隐藏编辑标记可检查分栏符。它不会新建一个节；分栏符控制文字流向，连续分节符控制可独立排版的范围。","例：标题一栏、中间正文两栏、结束语一栏。先选择中间正文，在更多栏选两栏并应用于所选文字；检查前后两处边界和标题、结束语是否仍通栏。恢复正文单栏时，定位正文所在节，在栏中选“一栏”并确认本节；其余节保持各自设置。恢复一栏不等于必须删除分节符；若删分节符，还会合并节并采用后节的格式，可能连带影响方向或页眉页脚。"],"boundary":"插入表格模拟两栏不等于真正分栏；页面并排也不会把正文自动变成两栏。","version":"已转换为Word 2016","id":"y2020q44","sources":[{"year":2020,"q":44,"type":"操作"},{"year":2023,"q":53,"type":"操作"}],"keys":["2020-44","2023-53"],"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"局部分栏与局部横向都要核对应用范围及分节边界，避免版式影响后文。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"Web版式、多页查看等属于视图选择，不能代替会影响打印的正文分栏。"}],"searchAliases":["分栏","更多栏","栏宽相等","分栏符","恢复单栏","分隔线","应用于","连续分节符"],"pointPresentation":{"0":{"title":"只选择要分栏的正文"},"1":{"title":"自然流向与提前换栏"},"2":{"title":"可设置哪些栏参数"},"3":{"title":"分栏与并排查看的区别"},"4":{"title":"更多栏：宽度、间距与分隔线","navigationLabel":"更多栏：宽度、间距与分隔线","blocks":[{"label":"入口辨析"},{"from":"按要求","label":"设置栏数和宽度"},{"from":"分隔线","label":"分隔线的作用"},{"from":"确定前","label":"确定与取消"}]},"5":{"title":"分栏范围：全文、当前节、所选部分","navigationLabel":"分栏范围：全文、当前节、所选部分","blocks":[{"label":"整篇与本节"},{"from":"只改中间","label":"局部正文"},{"from":"“插入点之后”","label":"后文的边界"}]},"6":{"title":"分栏符：提前从下一栏开始","navigationLabel":"分栏符：提前从下一栏开始","blocks":[{"label":"操作对象"},{"from":"在要移入","label":"步骤"},{"from":"后续文字","label":"结果"},{"from":"它不会","label":"分栏符与连续分节符"}]},"7":{"title":"例子与恢复单栏","navigationLabel":"例子与恢复单栏","blocks":[{"label":"目标与步骤"},{"from":"恢复正文","label":"恢复单栏"},{"from":"恢复一栏不","label":"保留必要节边界"}]}},"pointGroups":[{"title":"先确认分栏对象与范围","indices":[0,5,3]},{"title":"参数、文字流向与分栏符","indices":[2,4,1,6]},{"title":"完整例子与恢复","indices":[7]}]},{"q":41,"chapter":3,"section":"3.3","type":"操作","topic":"分节页眉","title":"页眉由节、链接状态与首页/奇偶页选项共同决定","trigger":"真题从同节页眉差异、普通页眉输入和长文档分节页眉考查真实规则。","conclusion":"先用分节确定不同内容的范围，再分别管理页眉和页脚的链接；首页不同、奇偶页不同会增加独立的页眉页脚类型。","points":["进入编辑：在打印布局中双击页面顶部，或用插入→页眉→编辑页眉。输入内容前确认当前页属于哪一节、哪一种页眉。","新节默认可能沿用前一节。看到“与上一节相同”时，先取消“链接到前一节”，再修改新节内容，否则可能同时改到前节。","页眉与页脚分别链接；首页页眉、奇数页页眉、偶数页页眉也各自链接到前一节的相同类型。只断开一种，不会自动断开其余类型。","封面、目录均无页眉，而正文单独设置：在正文前插入“下一页”分节符，再断开正文相应页眉链接。若正文页码位于页脚，还要单独检查页脚链接。","正文从1编号：在正文节插入页码，打开“设置页码格式”，选择起始页码1。取消链接改变的是页眉页脚内容的继承；起始页码决定编号。","页眉在页面上部，页脚在下部；可含文字、自动页码、日期时间、文档信息及图片，并可设置字符和段落格式。页脚可用插入→页脚→编辑页脚进入，已有区域也可双击。完成后用“关闭页眉和页脚”或Esc返回正文。页眉页脚编辑与正文编辑是不同状态；某个内置样式的初始对齐方式不是所有页眉页脚必须使用的对齐方式。","在同一节内，使用同一种页眉的各页共享该内容，修改其中一处即可反映到这些页，无需逐页输入。若后节该类型仍链接到前节，编辑还可能影响链接的节。要让“荷花”和其他花卉各有页眉，先在内容分界处用下一页分节符，再进入后节相应页眉、断开链接后修改；普通分页符只能换页。","“首页不同”为本节首页提供独立页眉页脚；独立并不等于必须留空，需要无页眉时检查并清空对应首页区域。“奇偶页不同”把奇数页和偶数页的页眉页脚分开编辑。这两种差异可以在一节内设置，不是每种不同都必须新增一节；跨章节分别填写不同内容时，再用节与链接控制。启用两项后，按页眉页脚区域显示的类型逐一检查，不能只修改普通页眉。","把光标放在需要显示页码的位置，再用插入→页眉和页脚→页码，选择位置和样式；已有页眉页脚内容时核对插入位置。自动页码由PAGE域显示所在页的编号，直接键入“1”只是普通文字。页码位置、字体与对齐可按要求调整，改变外观不等于改变编号起点。","在要设置的节内打开页码→设置页码格式。编号格式决定用1、2、3还是i、ii、iii等表示；“续前节”接着前节最后编号往下编，“起始页码”指定本节从几开始。例：前两页编号1、2，正文是新节，续前节时正文首页是3；设置起始页码1后，正文首页为1、后页为2。仅取消页脚链接不会自动重编；仅重编也不会自动清除前节显示的页码。","前提：在正文前建立下一页分节符，使前言和正文分属两节。前言节打开“设置页码格式”，选择i、ii、iii；正文节选择1、2、3，并设起始页码1。各节需要显示页码的位置还须插入页码；若要求不同页脚内容，分别处理页脚链接。完成后查看前言末页、正文首页和后页，不只看当前页。","“首页不同”区分首页的显示区域，不能据此断定第二个物理页面一定显示1。例如单节封面不显示页码、第二页要求显示1，可按要求把起始页码设为0；若有封面和目录等多页前置内容，采用正文另起一节、单独设置起号更便于控制。页面在文件中的先后位置与显示的页码是两件事。"],"boundary":"“首页不同”处理的是一节的首页，不能单独让封面和目录两页都无页眉；分页符换页但不建立新的节。","version":"已转换为Word 2016","id":"y2020q41","sources":[{"year":2020,"q":41,"type":"操作"},{"year":2023,"q":9,"type":"单选"},{"year":2024,"q":56,"type":"操作"},{"year":2021,"q":44,"type":"操作","page":7}],"keys":["2020-41","2023-9","2024-56","2021-44"],"comparison":{"headers":["设置","控制什么","不能代替什么"],"rows":[["分节符","划分独立设置范围","不会自动取消前节链接"],["链接到前一节","当前类型沿用前节内容","不会自动改起始页码"],["首页不同","本节首页单独一套内容","不能处理任意多页前置内容"],["奇偶页不同","奇数页、偶数页分开","不能自动按章节填写不同文字"]]},"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"不同页眉的范围由节划定；分页符只换页，不能建立独立页眉设置范围。"},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"页码用PAGE域保持动态，但在哪一节显示及如何起号还要检查链接与编号设置。"},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"页眉横线通常是段落边框，删页眉文字后仍有横线时应检查它。"}],"pointGroups":[{"title":"进入编辑，确认类型与共享关系","indices":[0,5,6,7,1,2]},{"title":"页码的显示、格式与编号","indices":[8,9,11]},{"title":"完整操作：前置部分与正文分别设置","indices":[3,4,10]}],"searchAliases":["页眉页脚","首页不同","奇偶页不同","续前节","起始页码","罗马数字","物理页","页码格式"],"pointPresentation":{"0":{"title":"进入页眉前先确认节与类型"},"1":{"title":"新节的前节链接"},"2":{"title":"页眉、页脚及各类型分别链接","navigationLabel":"页眉、页脚及各类型分别链接"},"3":{"title":"封面目录无页眉，正文独立"},"4":{"title":"正文从1起号"},"5":{"title":"页眉页脚可以放什么，怎样退出","navigationLabel":"页眉页脚可以放什么，怎样退出","blocks":[{"label":"内容与对象"},{"from":"页脚可","label":"进入页脚"},{"from":"完成后","label":"退出与注意"}]},"6":{"title":"同节同类型的页眉会联动","navigationLabel":"同节同类型的页眉会联动","blocks":[{"label":"哪些页共享内容"},{"from":"若后节","label":"跨节链接"},{"from":"要让","label":"操作例子"}]},"7":{"title":"首页不同、奇偶页不同与分节的关系","navigationLabel":"首页不同、奇偶页不同与分节的关系","blocks":[{"label":"首页不同"},{"from":"“奇偶页不同”","label":"奇偶页不同"},{"from":"这两种","label":"与分节的关系"},{"from":"启用两项","label":"检查类型"}]},"8":{"title":"插入页码与普通数字的区别","navigationLabel":"插入页码与普通数字的区别"},"9":{"title":"页码格式：续前节还是重新编号","navigationLabel":"页码格式：续前节还是重新编号","blocks":[{"label":"入口"},{"from":"编号格式","label":"三个设置分别管什么"},{"from":"例：","label":"续编与重编的结果"},{"from":"仅取消","label":"与页脚链接分别判断"}]},"10":{"title":"完整例子：前言用罗马数字，正文从1开始","navigationLabel":"完整例子：前言用罗马数字，正文从1开始","blocks":[{"label":"前提"},{"from":"前言节","label":"设置两节编号","steps":["前言节","正文节"]},{"from":"各节需要","label":"内容与链接"},{"from":"完成后","label":"验收"}]},"11":{"title":"首页不显示页码，不等于不参与编号","navigationLabel":"首页不显示页码，不等于不参与编号"}}},{"q":54,"chapter":3,"section":"3.3","type":"操作","topic":"页眉边框","title":"页眉横线应作为段落下边框设置","trigger":"题目要求改变页眉自动横线的颜色和宽度。","conclusion":"把光标放入页眉段落，打开“边框和底纹→边框”，设置线型、颜色和宽度，并把下边框应用于段落。","points":["横线通常是页眉段落的下边框，不是可拖动的普通直线形状。","“应用于：段落”决定边框随页眉段落宽度延伸。","预览区只保留下边框可避免四周都出现线。","删除页眉文字后横线仍在时，应检查页眉段落下边框；选中页眉段落，用“开始→边框→无框线”移除，不要反复按Delete找不存在的图片。","也可把“页眉”样式的段落边框改为无；使用该样式且未被直接格式覆盖的页眉段落会随之更新。"],"boundary":"修改页面边框会影响整页四周，修改下划线只作用于文字，两者都不能替代页眉段落边框。","id":"y2024q54","sources":[{"year":2024,"q":54,"type":"操作"},{"year":2022,"q":51,"type":"操作"}],"keys":["2024-54","2022-51"],"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"先进入正确节和正确类型的页眉，再设边框，避免因链接状态影响其他节。"},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"页眉横线也可通过页眉样式统一修改，直接格式可能覆盖样式规则。"},{"id":"y2020q60","label":"给表格设置全部框线","reason":"边框都需核对应用对象：页眉段落与整张表格的范围不同。"}],"pointGroups":[{"title":"把横线设为页眉段落下边框","indices":[0,1,2]},{"title":"删除残留横线或统一修改样式","indices":[3,4]}]},{"q":52,"chapter":3,"section":"3.3","type":"操作","topic":"样式","title":"统一修改同级标题应直接修改样式","trigger":"2023年第52题要求：一级标题已经应用同一样式，将段前间距设为20磅。原题使用Word2010，未指定样式名称；以下按Word2016路径，用“标题1”作操作示例。不是在原值上增加20磅。","conclusion":"修改这些标题实际使用的样式定义，把段前设为20磅；同一样式的对应属性按规则更新，局部直接格式例外另查。","points":["先检查目标段落确实使用“标题1”；仅手动加粗、放大成相同外观的段落不会因此受到样式修改。","开始→样式，右击标题1→修改→格式→段落，把段前设为20磅，确认后核对所有同级标题。","样式可同时包含字符与段落格式，后续应用同一样式的标题也会继承该规则；若某段仍不同，检查是否存在覆盖样式的直接格式。","需要把新规则用于以后基于模板创建的文档时，再明确设置模板保存范围；修改当前文档不等于改了所有旧文件。","样式是用名称保存的格式规则，有内置和自定义样式。段落样式面向段落，可包含字符和段落格式；字符样式面向选中文字的字符格式，不能用它设置整段段前距。官方对象分类还包含表格样式、列表样式，本节只识别对象，不展开操作。链接样式涉及段落与字符样式共享字符格式；不能把这个“链接”理解成模板同步开关。","先把插入点放进目标段落，查看开始选项卡的样式；需要更多项目时，打开样式组右下角的样式窗格。多段混合选择时逐段核对，不能只看字号或加粗外观。应用段落规则时确认目标是整段或多个目标段落；只处理几个字的字符样式，应先选中这些字。链接样式的局部选区行为更复杂，不把只选标题几个字直接当成已经建立整段标题结构。","先把一个示例段落排好并选中，在开始→样式库的“更多”菜单中选择“创建样式”，输入能说明用途且不冲突的名称，如“论文一级标题”，确认后检查该示例的样式身份。另一入口是右击选中文字→样式→创建样式；可在对话框中进入“修改”核对类型和格式。新样式有了名称，不代表其他外观相似的段落已自动改用它；仍须逐处应用。","建立段落样式时，核对“样式基准”和“后续段落样式”。基准说明以哪个已有样式的格式为基础，再设置本样式的差异；两个样式外观相同仍是两个定义。后续段落样式决定在当前样式段落后新建段落时使用的样式，例如标题后希望进入正文；它不会把文档中已存在的所有下一段重新套用样式。","选中下一个完整目标段落，在开始→样式中选择刚建立的名称；对其他同类段落继续应用。完成后重新检查各段的样式名，再核对字号和段前距；“名字相同但外观不同”可能有直接格式例外，“外观相同但名字不同”则没有共享同一规则。重新应用样式时也要看实际选区和样式类型，不把重复点击样式当成清除所有直接格式的通用办法。","要统一修改规则，先找准实际样式名，再右击它→修改；字号在修改窗口设置，段前等进入“格式→段落”，输入目标值后逐层确定。取消对话框不应当作已修改。另一种重定义方法是先把一段已使用目标样式的文字排好，再右击该样式→更新以匹配所选内容；这会吸收选区格式，先检查是否误带局部例外。两条路线都是改定义，和只给某段设置格式不同。","例如甲、乙使用标题1，丁也使用标题1但直接设为24磅；丙使用正文，只把字号做得像标题。把标题1改为22磅、段前20磅后，甲乙继承两项新规则；丁可仍为24磅，却继承20磅段前距；丙不因标题1定义改变而变。原因要逐属性判断：直接字号只覆盖字号，不会把该段从标题1中除名，也不自动覆盖段前距。","要恢复底层样式的字符格式，可选中文字后用Ctrl+Spacebar；去除手工段落格式用Ctrl+Q，二者处理范围不同。中文输入法可能截获Ctrl+Spacebar，先确认快捷键是否作用到Word，再查看结果。开始→字体→“清除所有格式”是另一项操作，不能保证仍保留原来的标题样式身份；用后重新核实样式和标题结构。它们都不是Delete删除文字，也不是删除样式定义。","修改段落样式中的“自动更新”涉及根据采用该样式的选择内容重新定义样式；启用后，某些手工格式操作可能影响同样式的其他段落。模板设置中的“自动更新文档样式”则从附加模板向文档更新样式。前者关注选区与样式定义，后者关注模板与文档；触发条件不同。使用前先确认这两个选项的实际状态。"],"boundary":"以下比较以未启用样式“自动更新”为前提。格式刷适合少量复制，不是全局规则；修改某一段的直接格式也不会自动更新所有同级标题。 “自动更新”与从模板更新文档样式是不同选项，参见本卡“两个自动更新”的辨析。","id":"y2023q52","sources":[{"year":2023,"q":52,"type":"操作"}],"keys":["2023-52"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"标题样式或适当大纲级别可以建立标题结构；只改字号外观不等于已建立结构。"},{"id":"y2021q56","label":"样式统一一份文档，模板给多份文档共同起点","reason":"当前文档样式规则确定后，可保存进模板；修改当前文档不自动更新所有旧文件。"},{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"想删所有某样式文字时要选中实例，修改或删除样式定义不是删除这些内容。"}],"pointPresentation":{"0":{"title":"先核实真正使用的样式"},"1":{"title":"示例：把标题1段前设为20磅"},"2":{"title":"检查继承与直接格式例外"},"3":{"title":"以后文档需要另看保存范围"},"4":{"title":"样式类型先看作用对象","navigationLabel":"样式类型先看作用对象"},"5":{"title":"确认段落、选区与当前样式","navigationLabel":"确认段落、选区与当前样式"},"6":{"title":"从示例格式建立命名样式","navigationLabel":"从示例格式建立命名样式","blocks":[{"label":"准备与步骤"},{"from":"另一入口","label":"其他入口"},{"from":"新样式有了","label":"结果与限制"}]},"7":{"title":"样式基准与后续段落样式","navigationLabel":"样式基准与后续段落样式"},"8":{"title":"把样式应用到其他目标段落","navigationLabel":"把样式应用到其他目标段落"},"9":{"title":"修改定义与更新以匹配所选内容","navigationLabel":"修改定义与更新以匹配所选内容","blocks":[{"label":"修改定义的步骤"},{"from":"取消对话框","label":"取消"},{"from":"另一种重定义","label":"其他入口与限制"}]},"10":{"title":"按属性排查直接格式例外","navigationLabel":"按属性排查直接格式例外"},"11":{"title":"去除例外与清除全部格式分开","navigationLabel":"去除例外与清除全部格式分开","blocks":[{"label":"按需要去除手工格式"},{"from":"中文输入法","label":"快捷键条件"},{"from":"开始→字体","label":"清除全部格式的区别"}]},"12":{"title":"两个“自动更新”不要混淆","navigationLabel":"两个“自动更新”不要混淆"}},"pointGroups":[{"title":"辨认样式与目标","indices":[4,5,0]},{"title":"建立并应用样式","indices":[6,7,8]},{"title":"修改规则并检查例外","indices":[1,9,2,10,11,12]},{"title":"转到模板复用","indices":[3]}],"searchAliases":["样式基准","后续段落样式","直接格式","创建样式","更新以匹配所选内容","标题同样式不同外观"]},{"q":56,"target":null,"page":9,"chapter":3,"section":"3.3","topic":"模板与样式","title":"样式统一一份文档，模板给多份文档共同起点","conclusion":"把标题、正文等格式定义为样式，再保存为模板，让不同文档从同一套规范开始。","points":["先明确标题、正文的字体、字号、段落间距和缩进，再分别建立样式；修改样式可更新使用它的内容，但已有直接格式可能仍覆盖某些属性，要检查例外。","把样式、页面设置和固定内容保存为模板；不含宏常用.dotx，含宏用.dotm，普通文档常用.docx。","从模板新建的是独立文档。修改新文档正文不会默认写回模板，修改模板也不会默认更新已经创建的所有旧文档。","实施顺序：建立样式→保存模板→基于模板新建文档→应用对应样式→检查局部例外。","模板不只是文件后缀，也可以保存样式、页面版式和固定起始内容。准备保存前，先确认当前文件是起始文档、某份已建文档，还是打开的模板本身。建立并应用样式后，核对标题身份和局部例外，保留每份文档都需要的固定文字，再把个人正文换成合适的提示文字。","在Word2016 Windows中，用文件→另存为→此电脑或浏览，指定保存位置与模板名称，在“保存类型”选择“Word模板（*.dotx）”，再保存。确需保留VBA宏时选“Word启用宏的模板（*.dotm）”；dotm表示可以容纳宏，不表示一定含宏或会自动执行。仅把文件名手改成.dotx不等于正确另存为模板，保存后要核对实际文件类型与位置。","文件→新建→个人（部分界面显示“自定义”），选择自己的模板，进入新文档后填写正文，再另存为自己的.docx；需保留宏的文档用相应.docm类型。结果是另一个文件，而不是正在编辑模板本身。若新建页找不到模板，先核对实际保存位置和自定义Office模板文件夹，再到新建页检查。不要把打开模板修改当作找不到模板时的同义操作。","要改以后新文档的起点，走文件→打开→此电脑或浏览，找到实际.dotx或.dotm文件并打开。先核对文件身份，再修改其固定正文或样式并保存，关闭模板后重新基于它新建一份文档检查。这里保存的对象是模板；“文件→新建”产生的文档要另存为自己的文件。区分两条入口，比只看窗口中的文字像不像模板更可靠。","在创建或修改样式时，若选“仅限此文档”，规则留在当前文档；要供以后基于同一模板新建的文档使用，应明确选择“基于该模板的新文档”等模板保存范围，并完成保存。另存一份模板是复用方案之一，不是唯一方式。因此课堂“新样式仅当前文档”应理解为所选保存范围的前提，不能泛化为样式永远不能跨文档使用。保存到模板也不等于所有旧文件已更新。","在旧文档未启用“自动更新文档样式”、也没有主动导入或更新样式的条件下，模板后来修改样式，不会仅因再次打开而自动改写该旧文档的样式。若启用该选项，Word可在打开文档时按可访问的附加模板匹配更新样式；主动更新也可复制模板样式并覆盖文档中的同名定义。它更新的是样式，不是把模板正文重新覆盖到旧文档，不能描述为所有已打开文件实时同步。","把含20磅标题样式和提示正文的模板保存，分别新建论文甲、乙并另存。只编辑甲的正文，核对乙和模板仍是各自内容；再打开模板，把标题样式改为24磅、提示正文改为新版并保存。按未启用模板样式更新的条件，甲乙保留自身正文和原样式；此后新建的丙取得24磅与新版提示。再改丙的正文，不会自动写回模板或甲乙。这是普通独立文档场景，不包含宏、外部链接等特殊机制。","样式保存某类内容的命名格式；主题协调字体、颜色和效果，入口在设计选项卡；模板保存可用于新文档的样式、版式与起始内容。它们可以配合使用，但选主题不等于给每段建立了正确的标题样式，也不等于把当前文件保存成模板。本节只辨认这几个对象，不把整体外观变化当成样式身份或模板同步的证据。"],"boundary":"保存模板不意味着所有旧文档自动更新；仍需新建时选模板或把相应样式应用到旧文档。","type":"分析","trigger":"围绕模板与样式的识别、应用与易错边界整理。","id":"y2021q56","sources":[{"year":2021,"q":56,"type":"分析"},{"year":2021,"q":57,"type":"分析","page":10}],"keys":["2021-56","2021-57"],"comparison":{"headers":["工具","适合什么","维护方式"],"rows":[["直接格式","某个词、某段的局部例外","只改选中内容"],["格式刷","把已有格式复制到少量目标","只改源处直接格式不会建立追踪更新；若目标也使用同一样式，仍受共同样式定义影响"],["样式","一份文档中同类内容统一","修改样式规则"],["模板","多份新文档共用起点","基于模板创建独立文档"]]},"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"先在单份文档建立可统一修改的样式，再把样式保存进模板供新文档使用。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"把标题样式写入模板，既统一外观，也为导航、自动目录提供结构。"}],"pointGroups":[{"title":"从样式规则到模板","indices":[0,3,4,1]},{"title":"保存、选用与编辑模板","indices":[5,6,7]},{"title":"核对影响范围","indices":[8,2,9,10]},{"title":"相关概念辨析","indices":[11]}],"pointPresentation":{"0":{"title":"先用样式定义同类内容"},"1":{"title":"模板中保存什么"},"2":{"title":"独立文档与默认影响范围"},"3":{"title":"从建立样式到核对例外"},"4":{"title":"先确认正在编辑哪个文件","navigationLabel":"先确认正在编辑哪个文件"},"5":{"title":"另存为模板：类型、名称与位置","navigationLabel":"另存为模板：类型、名称与位置","blocks":[{"label":"保存步骤"},{"from":"确需保留","label":"含宏时的类型"},{"from":"仅把文件名","label":"结果检查"}]},"6":{"title":"基于模板新建并另存文档","navigationLabel":"基于模板新建并另存文档","blocks":[{"label":"新建与保存步骤"},{"from":"结果是","label":"文件身份"},{"from":"若新建页","label":"找不到模板时"}]},"7":{"title":"打开并修改模板本身","navigationLabel":"打开并修改模板本身","blocks":[{"label":"打开编辑步骤"},{"from":"先核对","label":"修改、保存与检查"},{"from":"这里保存的对象","label":"与新建的区别"}]},"8":{"title":"样式的保存范围：当前文档还是模板","navigationLabel":"样式的保存范围：当前文档还是模板"},"9":{"title":"旧文档什么时候会取得模板新样式","navigationLabel":"旧文档什么时候会取得模板新样式","blocks":[{"label":"未启用模板样式更新时"},{"from":"若启用","label":"可能更新的条件"},{"from":"它更新的是","label":"更新对象与限制"}]},"10":{"title":"完整对照：两份旧文档与一份新文档","navigationLabel":"完整对照：两份旧文档与一份新文档"},"11":{"title":"样式、主题和模板各管什么","navigationLabel":"样式、主题和模板各管什么"}},"searchAliases":["另存为模板","个人模板","打开模板编辑","自动更新文档样式","dotx","dotm","模板不更新"]},{"q":70,"target":null,"chapter":3,"section":"3.3","topic":"页面背景","title":"图片水印、页面背景和衬于文字下方各有入口","conclusion":"Logo放在正文后方，可用图片水印、页面颜色的图片填充，或普通图片设为衬于文字下方。","points":["图片水印适合重复出现的淡化标识：设计→水印→自定义水印→图片水印，选择Logo并设置缩放、冲蚀等选项。需要选择或移动已有水印时，先进入页眉编辑。","普通图片需设置环绕、大小和位置，不会天然推广到每页。","页面背景图片走设计→页面颜色→填充效果→图片；若编辑画面可见而打印稿没有背景，检查文件→选项→显示→打印选项→打印背景色和图像，再查看打印预览。"],"boundary":"页面边框控制边缘线条，不负责把Logo作为整页背景；背景也不应遮挡正文。","type":"综合","trigger":"从页面背景的判断与应用整理。","id":"y2022q70","sources":[{"year":2022,"q":70,"type":"综合"}],"keys":["2022-70"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"普通背景图片需要设置文字环绕和锚定关系；衬于文字下方不会天然重复到每页。"}],"pointGroups":null},{"q":6,"chapter":3,"section":"3.4","type":"单选","topic":"删除表格","title":"Word表格：建表、改结构、转换、公式与排序","trigger":"制作一张能继续编辑的Word表格：先规划行列并建立表格，再选择对象、修改结构与尺寸；最后按需要转换、计算和排序。真题另考查Delete与Backspace的选区条件。","conclusion":"先按字段和记录建表，确认所选对象，再改变行列结构、尺寸与格式；转换、公式和排序都要核对操作范围及结果。清空文字、删除结构与重新划分单元格是不同操作。","points":["选择整表：使用表格左上角移动控点。按Delete通常只清空内容；明确删除表格结构可用表格工具→布局→删除→删除表格。整表确已选中时，Backspace也可删除表格。","文本转表格：插入→表格→文本转换成表格。用制表符、逗号等分隔列，用段落标记分隔行；先核对每行分隔符数量和目标列数。","排序：表格工具→布局→数据→排序。指定主要关键字、数据类型、升降序及有无标题行；文字可按可用的拼音、笔划等规则排序。","计算：把光标放入结果单元格，再用表格工具→布局→公式。=SUM(ABOVE)用于上方，=SUM(LEFT)用于左方；需精确范围时也可使用单元格引用。","Word表格公式是域。源数值修改后，应选择结果按F9或右击更新域，不能假定会像Excel一样立即重算。使用位置参数求和时，参与范围中的空单元格可先填0，避免范围或结果异常。","先把插入点放在需要建表的位置，按“字段作列、记录作行”规划，必要时另留表头和汇总行。插入→表格，在网格上移动指针预览行列，单击建立；需要明确行列数时选“插入表格”，填写列数、行数并核对自动调整选项后确定。建表后先数实际行列，避免把标题行漏算。","插入→表格→绘制表格适合边界不规则的表：先画外框，再按结构画横线、竖线；画斜线不等于生成两个能独立输入的单元格。快速表格插入可复用的预制表格，插入后应替换示例内容；它与只改变现有表格外观的“表格样式”不同。Excel电子表格创建的是可按Excel对象方式编辑的嵌入对象，不是普通Word单元格；本专题只辨认对象与链接关系。","课堂把网格入口称为“虚拟表格”，示图为10列8行；这只是网格选择范围，不能推成Word表格最多8行。课件另在“插入表格对话框”下列出63列、32767行；本轮未完成该极限的Word2016原生核验，保留为课堂待核数据，不推广成绘制、转换及所有操作共同的硬限制。日常先选适合数据的行列数，再用插入行列扩展。","需要选结构时，先辨明目标是单元格、行、列还是整表。鼠标可在单元格边缘、行左侧、列顶部的相应位置选择；只拖选格内几个字是文字选区，不等于选中单元格。移动指针到表格后，左上角四向箭头移动柄可选整表；不要把它和右下角缩放柄混用。操作前观察选区究竟覆盖哪些单元格。","在打印布局中显示表格控点，拖左上移动柄可移动整表；右下缩放柄改变整表尺寸，不是移动位置。需要精确定位或检查环绕时，用表格属性→表格，分别查看对齐、左缩进和文字环绕。改整表尺寸后仍要检查列宽、换行与分页；不能把缩放表格理解为按比例缩放所有文字的字号。","先在目标行或列内放置插入点，表格工具→布局→行和列，选择在上方/下方插入行或在左侧/右侧插入列；插入方向以当前对象为参照。删除时用布局→删除中的单元格、行、列或表格，并核对确认/移动单元格的选项。删除单元格可能让余下单元格左移或上移，和删整行、整列不是一回事。Delete清内容与删结构的区别见前面的选区规则，不能把只在格内闪烁的光标当成整表已选中。","在最后一个单元格按Tab会增加一行；在其他单元格按Tab通常移到下一单元格。需要在单元格里输入制表符时用Ctrl+Tab。Enter在单元格文字中建立段落，不能无条件当作“增加表格行”；课堂在表格外侧的特定Enter入口，应先确认插入点位置，尚未按所有位置原生实测。","先选中需要合并的相邻单元格，表格工具→布局→合并单元格。合并改变网格结构，原有内容应保留；合并后检查文字顺序、段落及对齐，不要把它当作删掉其他格的文字。Word合并与某些软件提示只保留左上角内容的场景不能混为一谈。若只想让同一行文字居中，先判断是否真的需要合并结构。","把插入点放入待拆的单元格，或选择目标单元格，布局→拆分单元格，设置拆成的列数、行数后确定。需要先合并选区再拆分时，核对对话框提供的对应选项。拆分是重新划分单元格，不保证自动还原以前每格各自的文字；完成后重新安排内容。若目标是准确回到刚才合并前的结构和内容，优先考虑撤销，而非假定拆分就是逆操作。","把插入点放在应成为第二张表首行的任一单元格，布局→拆分表格；Ctrl+Shift+Enter也是课堂给出的入口。结果在该行上方分开，出现两张上下排列的表，中间有段落；这是按行拆表，不是把列直接劈成左右两张表。重新接合前确认两表之间没有要保留的正文，并按课堂要求检查表格文字环绕为“无”，再删除两表之间的段落标记，核对接合后的网格。列宽和结构不同的复杂接合结果仍须逐格检查。","先显示编辑标记，区分真正的制表符、连续空格和段落标记；仅看视觉上对齐不能判断文本有几列。文本中本来含逗号时，宜用制表符分列以免误拆；同一记录不要随意另起段落。进入文本转换对话框后核对列数、分隔符和自动调整，确定后检查每条记录是否仍与自己的字段对应。嵌套表、合并单元格或不规则记录不应假定能无损往返。","先选中要转换的行或整张表格，表格工具→布局→数据→转换为文本，在对话框中选择制表符、逗号或其他分隔方式，再确定。结果保留文字并用所选分隔方式组织内容，原来的可编辑表格网格不再保留；选制表符时，同一行各格之间用制表符分隔，行与行之间用段落标记分开；原单元格若已有多个段落，也要检查转换后的段落关系。它不是按Delete清空格内文字，也不是把表格复制成图片。转换后检查行列内容的对应关系，必要时撤销并换合适分隔符。","ABOVE表示同列上方，BELOW表示同列下方，LEFT表示同行左方，RIGHT表示同行右方；方向以当前公式所在单元格为参照，不是以整张表的左上角或屏幕阅读方向为参照。位置参数不包括标题行中的数值；空单元格、合并格和数据布局可能影响期望范围，先检查参与对象，不能仅凭方向词推定任意复杂表中的结果。","例如表头“姓名、成绩”下有两条成绩80、95，第三条汇总格放在成绩列下方：选空白汇总格插入=SUM(ABOVE)，结果为175。把80改成90后，先看显示值是否仍是175，选中结果域按F9后核对185。Word会在插入公式、打开文档等时机计算，也可手动更新；不能写成“永远实时联动”或“只有按F9才会计算”。选中了整表时，F9可用于更新该表内的公式域。","需要明确单元格时，可用A1引用：字母表示列，数字表示行；例如=SUM(B2:B3)限定B2到B3，=A2*B2使用这两个单元格。也可按任务使用AVERAGE、MAX、MIN等支持函数。公式对话框中的数字格式控制结果呈现，如小数位；它不能修复引用范围选错。结构增删后检查公式实际引用与域结果，不把Word表格当作Excel工作表自动复制公式的完整替代。","选中要排序的表格（或明确目标范围），布局→排序，先确认是否“有标题行”，再选主要关键字、类型与升降序；同组需要进一步区分时再设次要和第三关键字，课堂与Word对话框最多提供三级关键字。数字按数值大小排，文本按字符规则排，日期按日期含义排；类型选错时，9、80、100可能不会按数值顺序出现。确认后核对姓名等同一记录字段是否跟随移动、标题是否仍在顶部；别只选一列排序而打乱对应关系。"],"boundary":"同样一个Delete或Backspace，光标、文字选区、单元格选区与整表选区会得到不同结果；先确认选中了什么。","id":"y2024q8","sources":[{"year":2023,"q":6,"type":"单选"},{"year":2024,"q":8,"type":"单选"}],"keys":["2023-6","2024-8"],"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"Word表格公式与题注、交叉引用同样使用域，源内容改变后要核对并更新域。"},{"id":"y2024q10","label":"清除内容只移除值或公式，不清除格式","reason":"Word表格和Excel单元格的Delete通常清空内容，删除结构需使用对应删除操作。"},{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"文本转表格和CSV导入都要先确认分隔符与字段结构，不能只按视觉间距判断列。"}],"pointGroups":[{"title":"建表与选择对象","indices":[5,6,7,8,9]},{"title":"修改结构、合并与拆分","indices":[0,10,11,12,13,14]},{"title":"文本与表格双向转换","indices":[1,15,16]},{"title":"公式：范围、显示与更新","indices":[3,4,17,18,19]},{"title":"排序与记录对应","indices":[2,20]}],"pointPresentation":{"0":{"title":"选中整表后清内容或删结构","navigationLabel":"选中整表后清内容或删结构"},"1":{"title":"按分隔符把文本转换为表格","navigationLabel":"按分隔符把文本转换为表格"},"2":{"title":"排序先确定字段与数据类型","navigationLabel":"排序先确定字段与数据类型"},"3":{"title":"在结果单元格插入公式","navigationLabel":"在结果单元格插入公式"},"4":{"title":"修改数据后核对并更新公式域","navigationLabel":"修改数据后核对并更新公式域"},"5":{"title":"网格与插入表格对话框","navigationLabel":"网格与插入表格对话框","blocks":[{"label":"规划对象"},{"from":"插入→表格","label":"建立步骤"},{"from":"建表后","label":"结果检查"}]},"6":{"title":"绘制、快速表格与Excel电子表格","navigationLabel":"绘制、快速表格与Excel电子表格"},"7":{"title":"课堂所列行列上限怎样使用","navigationLabel":"课堂所列行列上限怎样使用"},"8":{"title":"先选单元格、行、列还是整表","navigationLabel":"先选单元格、行、列还是整表"},"9":{"title":"移动整表与改变整表大小","navigationLabel":"移动整表与改变整表大小"},"10":{"title":"插入与删除行列","navigationLabel":"插入与删除行列","blocks":[{"label":"插入步骤"},{"from":"删除时","label":"删除入口"},{"from":"删除单元格","label":"对象与结果的区别"}]},"11":{"title":"用Tab增加末行的条件","navigationLabel":"用Tab增加末行的条件"},"12":{"title":"合并单元格：先选相邻区域","navigationLabel":"合并单元格：先选相邻区域"},"13":{"title":"拆分单元格不等于撤销合并","navigationLabel":"拆分单元格不等于撤销合并"},"14":{"title":"拆分表格与重新接合","navigationLabel":"拆分表格与重新接合","blocks":[{"label":"拆表步骤"},{"from":"结果在","label":"方向与结果"},{"from":"重新接合","label":"接合的前提"}]},"15":{"title":"转换前检查分隔符，转换后检查字段","navigationLabel":"转换前检查分隔符，转换后检查字段"},"16":{"title":"把表格转换为文本","navigationLabel":"把表格转换为文本"},"17":{"title":"公式四个方向相对于结果格","navigationLabel":"公式四个方向相对于结果格"},"18":{"title":"完整例子：插入、修改数据与更新","navigationLabel":"完整例子：插入、修改数据与更新"},"19":{"title":"指定范围与数字格式分别设置","navigationLabel":"指定范围与数字格式分别设置"},"20":{"title":"排序让整条记录一起移动","navigationLabel":"排序让整条记录一起移动"}},"searchAliases":["插入表格","绘制表格","快速表格","合并单元格","拆分单元格","拆分表格","移动柄","转换为文本","RIGHT","BELOW","Tab末格","Word表格：转换、公式、排序与删除"]},{"q":63,"chapter":3,"section":"3.4","type":"综合","topic":"表格对齐","title":"整张表格居中与单元格内容居中","trigger":"题目比较段落居中、表格属性和表格工具中的水平居中。","conclusion":"整表在页面中居中，应设置表格对齐方式；单元格水平居中只改变格内内容。","points":["整表居中：右击表格→表格属性→表格→对齐方式“居中”。它改变表格对象相对排版区域的位置。","格内文字水平居中：选择目标单元格内容，使用开始→段落→居中；文字在各自单元格内移动，表格宽度与位置不因此改变。","格内水平与垂直位置一起设置：使用表格工具→布局→对齐方式的九种对齐选项；表格属性→单元格也可设置垂直对齐。","确认结果时观察表格左右留白和文字在单元格中的位置，分别判断两个目标是否达到。","先选目标行、列或单元格，在表格工具→布局→单元格大小填写高度或宽度；也可在表格属性的“行”“列”页精确设置。鼠标可拖表格边界直观调整，但拖哪条边界和选区会影响相邻区域，完成后核对实际宽度及文字换行。课堂还给出用标尺调整行高、列宽的入口；先显示适用标尺，再拖对应边界。不要用字号代替列宽，也不要用段前间距代替行高。","表格属性→行中勾选指定高度时，继续核对行高值是固定值还是最小值。最小值允许行随内容增高；固定值限制行高，内容过高可能显示不全。遇到文字或图片被截，先查行高、单元格边距和段落行距，不要立即判断内容丢失。表格行高与段落“固定值行距”是两层不同设置。","布局→自动调整可按各列内容调整列宽，或按窗口调整以适应可用宽度；固定列宽用于停止随内容自动调整列宽。需要选定的多行等高或多列等宽时，先选择这些行列，再用平均分布各行/各列。平均分布的对象是选区，不能不看选择范围就承诺整表全部相等；它也不会替你重排每格中的文字。","单元格边距控制格内文字到边框的留白；在表格工具→布局→单元格边距，或表格属性→单元格→选项核对作用范围。文字方向改变所选单元格内文字的排列方向，不能当作把整个表格旋转。改变边距、方向或对齐后仍要检查行高与换行，九种对齐也不等于“自动调整列宽”。","2020年第63题还比较“在表左选全部行”“用移动柄选整表”之后的段落居中，与表格工具中的单元格水平居中。前两项的选区与只选格内文字不同，不能用“段落居中只移动格内文字”一句话全部排除。未署名配套答案选择不能让整表居中的单元格对齐项；这两种整表选区加段落按钮的具体Word2010/2016行为尚待原生核验。照着操作整表居中时，本卡给出的表格属性入口已有明确依据。"],"boundary":"先分清“表格这个对象居中”还是“单元格里的文字居中”，两者按钮和结果不同。","version":"已转换为Word 2016","id":"y2020q63","sources":[{"year":2020,"q":63,"type":"综合"}],"keys":["2020-63"],"comparison":{"headers":["要求","规范入口","观察结果"],"rows":[["整张表格居中","表格属性→表格→居中","表格左右留白对称"],["格内文字水平居中","所选内容→段落居中","字在单元格内左右居中"],["格内文字上下居中","表格工具→布局→对齐方式","字在单元格内垂直居中"]]},"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"选择格内文字时，段落对齐作用于格内段落；整表选区要另看本题前提，不能一概套用。"},{"id":"y2020q60","label":"给表格设置全部框线","reason":"表格格式操作依赖选区与应用范围，整表和所选单元格不能混为一谈。"}],"pointPresentation":{"0":{"title":"用表格属性设置整表居中","navigationLabel":"用表格属性设置整表居中"},"1":{"title":"只给格内文字设置段落居中","navigationLabel":"只给格内文字设置段落居中"},"2":{"title":"设置单元格内容的水平与垂直位置","navigationLabel":"设置单元格内容的水平与垂直位置"},"3":{"title":"分别核对表与文字的位置","navigationLabel":"分别核对表与文字的位置"},"4":{"title":"调整行高列宽的两条入口","navigationLabel":"调整行高列宽的两条入口"},"5":{"title":"固定行高与最小行高","navigationLabel":"固定行高与最小行高"},"6":{"title":"自动调整和平均分布解决不同问题","navigationLabel":"自动调整和平均分布解决不同问题"},"7":{"title":"单元格边距与文字方向","navigationLabel":"单元格边距与文字方向"},"8":{"title":"真题中整表选区与段落按钮的条件","navigationLabel":"真题中整表选区与段落按钮的条件"}},"pointGroups":[{"title":"整表位置与内容对齐","indices":[0,1,2,3]},{"title":"尺寸、留白与文字布局","indices":[4,5,6,7]},{"title":"真题选区条件","indices":[8]}],"searchAliases":["行高","列宽","平均分布","自动调整","单元格边距","固定行高"]},{"q":60,"chapter":3,"section":"3.4","type":"综合","topic":"表格边框","title":"给表格设置全部框线","trigger":"题目比较绘制表格、边框菜单和表格属性等设置全部框线的方法。","conclusion":"选中表格后使用“开始”或“表格工具-设计”中的边框菜单设置“所有框线”最直接。","points":["边框可作用于单元格、所选区域或整张表格。","表格属性中的“边框和底纹”可精确设置线型、颜色、宽度和应用范围。","绘制表格适合补画局部线条，不适合为已有大表逐条重画。","屏幕上的表格网格线只是帮助识别单元格，不会打印。要求打印出全部线条时必须设置实际边框；可到打印预览核对，不能仅凭编辑画面中的虚线判断完成。","在表格中定位或选中目标区域，表格工具→设计→边框可选所有框线、外侧或特定边界；要控制线型、颜色、宽度，进入边框和底纹，检查预览和“应用于”。只给部分单元格加线时，不要把应用对象留成整表。边框改变线条外观，不能代替插入行列、合并或拆分结构。","底纹给表格或选中单元格设置背景；文字突出显示颜色作用于文字，二者不是同一对象。表格工具→设计中的表格样式可一次采用一组配套格式，再按任务检查标题行、汇总行、镶边行等样式选项。样式的“标题行”只是外观条件，跨页每页重复仍要单独设置重复标题行。"],"boundary":"边框快捷菜单按当前选区应用；也可把光标置于任意单元格，经表格属性→边框和底纹，把“应用于”设为“表格”。光标位于表格内即可显示表格工具，不要求先选中整表。","version":"已转换为Word 2016","id":"y2020q60","sources":[{"year":2020,"q":60,"type":"综合"}],"keys":["2020-60"],"related":[{"id":"y2020q63","label":"整张表格居中与单元格内容居中","reason":"设置前先确定选中的是表格对象还是格内文字；整表边框和格内对齐作用范围不同。"},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"边框设置都要核对“应用于”，页眉段落下边框不能用页面或表格边框替代。"}],"pointGroups":[{"title":"线条、网格与作用范围","indices":[0,1,2,3,4]},{"title":"背景与成套格式","indices":[5]}],"pointPresentation":{"0":{"title":"边框先看作用对象","navigationLabel":"边框先看作用对象"},"1":{"title":"从属性精确设置边框","navigationLabel":"从属性精确设置边框"},"2":{"title":"绘制局部边界与批量设框线","navigationLabel":"绘制局部边界与批量设框线"},"3":{"title":"网格线与真实边框","navigationLabel":"网格线与真实边框"},"4":{"title":"先定线条再核对应用范围","navigationLabel":"先定线条再核对应用范围"},"5":{"title":"底纹与表格样式","navigationLabel":"底纹与表格样式"}},"searchAliases":["所有框线","表格网格线","表格底纹","表格样式"]},{"q":62,"chapter":3,"section":"3.4","type":"综合","topic":"跨页表格","title":"跨页表格重复标题行","trigger":"题目要求表格跨多页时每页顶部都显示标题行。","conclusion":"让跨页表格自动重复表头，应选中从第一行开始的连续标题行，再用表格工具→布局→重复标题行。","points":["重复行必须包含表格第一行；多行表头应连续选中，不能只选表格中部某一行作为重复表头。","也可打开表格属性→行，勾选“在各页顶端以标题行形式重复出现”。","该效果在打印布局和打印结果中查看；后续页的重复标题由首段表头生成，应修改第一页的原始标题行。","表格因内容自然跨页时会重复标题；在表格内部手动插入分页符不会得到同样的自动重复效果。","表格属性→行中的“允许跨页断行”控制一条表格行能否分到两页；需要一条记录尽量完整留在同页时，选中相应行检查这个选项。它不负责让表头重复，也不等于禁止整张表跨页。行内容超过一页或另有固定高度、段落分页约束时，必须检查实际分页，不能保证取消选项便解决所有跨页问题。","依次检查是否仍是同一张表、选区是否包含第一行、是否连续多行、是否采用自然分页，并切到打印布局查看。拆成两张表后，下表是另一个对象，不能只沿用上表的首行判断。不要靠在每页手工复制表头来冒充自动重复，否则修改原表头后容易出现多份文字不一致。"],"boundary":"“表格样式选项→标题行”主要影响样式外观，不等于跨页重复标题；页面页眉也不是表格表头。","version":"已转换为Word 2016","id":"y2020q62","sources":[{"year":2020,"q":62,"type":"综合"}],"keys":["2020-62"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"重复标题行应在打印布局核对，屏幕查看方式会影响是否看得到分页效果。"},{"id":"y2024q58","label":"选中第3行后冻结可保持前两行可见","reason":"Word重复表头用于跨页打印；Excel冻结窗格只用于滚动查看，两者用途容易混淆。"}],"pointPresentation":{"0":{"title":"从首行开始选择连续表头","navigationLabel":"从首行开始选择连续表头"},"1":{"title":"在行属性中设置重复","navigationLabel":"在行属性中设置重复"},"2":{"title":"在打印布局核对原始表头","navigationLabel":"在打印布局核对原始表头"},"3":{"title":"自然跨页与手动分页的区别","navigationLabel":"自然跨页与手动分页的区别"},"4":{"title":"允许跨页断行与重复表头分开","navigationLabel":"允许跨页断行与重复表头分开"},"5":{"title":"排查表头没有重复","navigationLabel":"排查表头没有重复"}},"pointGroups":[{"title":"设置并核对重复标题","indices":[0,1,2,3]},{"title":"跨页行与故障排查","indices":[4,5]}],"searchAliases":["允许跨页断行","标题行不重复","多行表头"]},{"q":69,"target":null,"chapter":3,"section":"3.4","topic":"链接与嵌入","title":"链接Excel表格可随源数据更新，嵌入保留独立副本","conclusion":"希望Word表格跟随Excel变化，应采用粘贴链接或链接对象；普通粘贴、嵌入和图片通常不会自动跟随源文件。","points":["复制Excel区域后，在Word选择“链接并保留源格式”或“链接并使用目标样式”；也可用开始→粘贴→选择性粘贴→粘贴链接。","更新链路：修改并保存Excel源数据→Word刷新链接或按提示更新→核对Word中的值。更新时机仍受自动更新和安全设置影响。","链接依赖源文件位置和访问权限；移动、重命名或失去权限可能使更新失败。Word暂时还能显示旧值，不代表链接正常。","源格式/目标格式决定外观，链接/嵌入决定数据关系；两者要分别判断。","普通Word表格由Word的单元格、行列工具编辑；插入的Excel电子表格或嵌入Excel对象可用相应对象工具编辑；粘贴成图片只留下画面。相同外观不证明相同对象，更不能据此推断是否链接源文件。先检查选中后的工具和粘贴方式，再判断后续修改与更新范围。"],"boundary":"链接是数据关系，源格式/目标格式是外观选择，两者不是同一个维度。","type":"综合","trigger":"从链接与嵌入的判断与应用整理。","id":"y2022q69","sources":[{"year":2022,"q":69,"type":"综合"}],"keys":["2022-69"],"comparison":{"headers":["粘贴方式","源Excel修改后","Word里保存什么"],"rows":[["粘贴链接","允许并刷新后可更新","链接关系及显示内容"],["嵌入Excel对象","不跟随源文件变化","可独立编辑的Excel副本"],["普通表格粘贴","不跟随源文件变化","Word表格内容"],["图片","不跟随源文件变化","图像，不能按单元格修改"]]},"related":[{"id":"y2021q9","label":"跨工作簿引用要指明工作簿和工作表","reason":"跨文件链接都依赖源位置和更新状态，看到旧缓存值不能证明源文件已同步。"},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"保留链接关系、可编辑对象结构和源格式是不同选择，也影响PowerPoint图表的更新与动画。"}],"pointGroups":[{"title":"辨认对象、数据关系与外观","indices":[4,0,3]},{"title":"更新与源文件依赖","indices":[1,2]}],"pointPresentation":{"4":{"title":"先区分三种“表格”对象","navigationLabel":"先区分三种“表格”对象"}}},{"q":45,"chapter":3,"section":"3.5","type":"操作","topic":"图片尺寸","title":"图片尺寸、纵横比与裁剪","trigger":"两道连续操作题考查为何宽高不能同时指定，以及如何在尺寸要求和不变形之间取舍。","conclusion":"锁定纵横比时修改一边会按比例改变另一边；目标比例与原图不同时，若要填满精确尺寸且不失真，应先裁剪到目标比例再缩放。","points":["关闭纵横比可以强制输入宽高，但可能拉伸图像。","裁剪改变可见范围，缩放改变显示尺寸，两者解决的问题不同。","实际排版应优先保持人物和图形不变形。","2020年题设原图高8.5 cm、宽6 cm。锁定比例后，高改为6 cm时宽约4.24 cm；宽改为5 cm时高约7.08 cm。目标高6 cm、宽5 cm的宽高比为5∶6，与原图6∶8.5不同。","先把插入点放到需要的位置，插入→图片，选择本地图片后插入；联机图片是另一个来源入口，受网络和可用服务影响。单击图片看到大小控点，再进入图片工具→格式；没有出现对应工具时，先检查是否选中了图片本身。新插入/粘贴图片常以嵌入型出现，但默认方式可以在Word选项中改变，不能只按“图片”名称猜当前环绕。","先选图片，再拖大小控点作视觉调整；需要精确尺寸时，在图片工具→格式→大小或大小和位置对话框中填写高度、宽度，并检查“锁定纵横比”。保持比例时改一边会联动另一边；需要稳定保持比例，可用锁定选项，不把所有对象、所有控点的拖动规则混成一句“按Shift一定不变形”。最终以实际宽高和主体形状核对。","先算目标宽高比，再选图片→图片工具→格式→裁剪，拖裁剪控点改变可见边界；需要构图时移动图片在裁剪框中的位置，完成后退出裁剪。裁掉部分画面后，重新核对比例，再设置成品尺寸。例如目标宽5、高6，就先得到5∶6的可见画面，再缩放到5 cm×6 cm；不能既强留全部原画面、又保持原比例、又任意指定不匹配的宽高。","普通裁剪后，被裁去的部分通常仍保存在文件中，可重新调整裁剪范围；若已删除裁剪区域并保存，不能仅靠扩展裁剪框取回原画面；保存前是否仍可撤销应按当前状态检查。裁剪不等于压缩，也不等于把图片替换为另一张。需要保护原始素材时保留原文件，完成后检查画面边缘和主体是否被误切。","要换素材时，选中原图片，在图片工具→格式→更改图片选择新图片；这条路线与删掉原图再插入不同。新旧图片比例、主体位置不同，即使部分格式沿用，也必须重新检查宽高、裁剪、环绕和遮挡关系。涉及PowerPoint的更改图片动画题只作已有跨章联系，不冒称Word本题要求。","选中图片后，图片工具→格式中的更正用于亮度、对比度等调整；颜色用于饱和度、色调、重新着色等；图片边框和图片效果处理边缘与视觉效果。这些改变外观，不会自动修正对象环绕或与其他图形的层级。先看题目要求哪个属性，再检查调整结果，别把图片颜色和形状填充混用。"],"boundary":"考试若只问机械步骤可能选择取消锁定；规范成品还要检查是否产生视觉失真。","id":"merged-9","sources":[{"year":2020,"q":45,"type":"操作"},{"year":2020,"q":46,"type":"操作"}],"keys":["2020-45","2020-46"],"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"图片看起来缺一块可能来自固定行距裁切，应先排除排版原因再改图像尺寸。"},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"替换图片后要重新检查纵横比和裁剪，保留对象效果不保证新图片构图合适。"},{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"确定图片尺寸后，再选择它与文字的排版关系。"}],"pointPresentation":{"0":{"title":"强制宽高可能拉伸","navigationLabel":"强制宽高可能拉伸"},"1":{"title":"裁剪与缩放的区别","navigationLabel":"裁剪与缩放的区别"},"2":{"title":"先保护人物和图形比例","navigationLabel":"先保护人物和图形比例"},"3":{"title":"按原题尺寸计算联动结果","navigationLabel":"按原题尺寸计算联动结果"},"4":{"title":"插入图片并确认选中对象","navigationLabel":"插入图片并确认选中对象"},"5":{"title":"用控点调整与精确输入尺寸","navigationLabel":"用控点调整与精确输入尺寸"},"6":{"title":"按目标比例裁剪，再缩放","navigationLabel":"按目标比例裁剪，再缩放","blocks":[{"label":"操作链"},{"from":"裁掉部分画面后","label":"结果检查"},{"from":"例如目标","label":"完整取舍例子"}]},"7":{"title":"裁剪通常隐藏画面，删除裁剪区域另算","navigationLabel":"裁剪通常隐藏画面，删除裁剪区域另算"},"8":{"title":"更改图片后重新核对版式","navigationLabel":"更改图片后重新核对版式"},"9":{"title":"图片更正、颜色与边框分开","navigationLabel":"图片更正、颜色与边框分开"}},"pointGroups":[{"title":"插入、选中与设置尺寸","indices":[4,5,0]},{"title":"比例、裁剪与完整例子","indices":[1,2,3,6,7]},{"title":"替换与外观调整","indices":[8,9]}],"searchAliases":["插入图片","锁定纵横比","裁剪取景","删除裁剪区域","更改图片"]},{"q":53,"chapter":3,"section":"3.5","type":"操作","topic":"图片环绕","title":"图片环绕取决于对象是嵌入型还是浮动型","trigger":"真题从环绕菜单入口和版面结果考查图片与正文关系。","conclusion":"嵌入型把图片当成文本行里的字符；其他环绕方式让图片成为锚定到段落的浮动对象。先确定是否要绕排，再选环绕边界。","points":["先选中图片，再从图片工具→格式→环绕文字或图片旁的布局选项设置。嵌入型不能像浮动对象一样随意拖到正文任意位置。","四周型按外接矩形绕排；紧密型、穿越型依据环绕轮廓。图片背景、透明区和编辑环绕顶点会影响效果，不能只凭图片外形名称判断。","浮动图片还要区分“随文字移动”和“在页面上固定位置”；环绕方式与位置关系是两个设置，改变前者不等于自动锁定后者。","嵌入型图片作为文本行内的一个对象参加排版，能够单独单击选中、复制、剪切、删除和设置大小，也可以把它移到另一个文字插入位置。它不能像浮动对象那样独立安排在页面任意坐标，更不能直接把“不能按浮动方式多选/组合”缩写成“不能选中”。先单选图片检查环绕，需要组合时再改成适合的非嵌入方式。","嵌入型占文本行；四周型绕外接矩形；紧密型贴近环绕轮廓；穿越型还涉及轮廓内可穿越区域；上下型只在对象上、下排文字。衬于文字下方和浮于文字上方允许图文重叠，分别把对象放到正文后面或前面。矩形不透明图在四周、紧密等方式下可能看起来相近，只有知道轮廓与空白区域的条件才能进一步判断；不可仅凭这种矩形截图反推出唯一环绕方式。","选中图片后，右键→环绕文字可选择所需方式；图片工具→格式→环绕文字及图片旁布局选项是其他已核入口。右键“大小和位置”的布局设置与“设置图片格式”窗格不是同一个界面，不要把不同入口的选项拼接成一条路径。2025年第47题未署名配套答案把B项列为不正确；B/C涉及的具体菜单布局仍待原生Word2016核对，按已核实入口完成操作即可。","Word2016可在文件→选项→高级→剪切、复制和粘贴中，修改“将图片插入/粘贴为”的默认文字环绕。它影响之后插入/粘贴的图片，检查当前图片仍要看当前对象的布局，不能以默认设置替代现场判断。形状、艺术字和文本框也应检查各自的环绕与所在区域，不把课堂默认示例写成所有文档永远相同。","浮动对象与某一段落保持锚定关系；“随文字移动”与“在页面上固定位置”决定正文变动时的位置策略。锁定锚点和固定页位置不是同一个开关，锚定关系也不会因固定位置而消失。需要检查时开启对象锚点显示，再核对对象所附段落和位置选项；不要据此承诺删除相关段落后图片仍永远保留。细节受锚定段落、分页和布局条件影响。","先单独选对象确认类型，查看当前环绕，再决定要它随文字占行、让文字绕排，还是允许图文重叠；设置大小和位置后，再检查对象与其他对象的前后关系。需要多选组合时，先把参与对象调整为可共同选择的浮动对象，再选择外框。若嵌入图只显示一部分，沿已有行距卡片检查固定值行距，不要用更改环绕掩盖未查清的原因。"],"boundary":"多行正文沿图片左右两侧形成绕排时，可排除嵌入型和上下型；同一文字行里图片旁有字不能据此排除嵌入型。仅凭一张矩形截图，可能无法唯一分辨四周型与紧密型。","id":"y2025q47","sources":[{"year":2024,"q":53,"type":"操作"},{"year":2025,"q":47,"type":"操作"},{"year":2022,"q":52,"type":"操作"},{"year":2021,"q":7,"type":"单选","page":2}],"keys":["2024-53","2025-47","2022-52","2021-7"],"comparison":{"headers":["环绕方式","文字如何排布"],"rows":[["嵌入型","图片像一个字符占据文本行"],["四周型","围绕图片外接矩形"],["紧密型","贴近可用的环绕轮廓"],["穿越型","可进入环绕轮廓允许的内部空隙"],["上下型","只在图片上方、下方排文字"],["衬于文字下方","文字覆盖在图片上方"],["浮于文字上方","图片可能遮住正文"]]},"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"嵌入型图片占文本行，若显示不全应检查段落固定行距。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合多个对象前，嵌入型图片通常须先改成可共同选择的非嵌入型对象。"},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"文字环绕管对象与正文的关系，两个浮动对象谁遮挡谁则由叠放顺序控制。"}],"pointPresentation":{"0":{"title":"选图片后设置环绕","navigationLabel":"选图片后设置环绕"},"1":{"title":"矩形边界与轮廓边界","navigationLabel":"矩形边界与轮廓边界"},"2":{"title":"环绕方式与位置关系分别设置","navigationLabel":"环绕方式与位置关系分别设置"},"3":{"title":"嵌入式也能被选中","navigationLabel":"嵌入式也能被选中"},"4":{"title":"七种环绕先看文字排在哪里","navigationLabel":"七种环绕先看文字排在哪里"},"5":{"title":"右键入口与“布局”名称不要混淆","navigationLabel":"右键入口与“布局”名称不要混淆"},"6":{"title":"默认嵌入型是可修改的设置","navigationLabel":"默认嵌入型是可修改的设置"},"7":{"title":"移动浮动图片时同时看锚点","navigationLabel":"移动浮动图片时同时看锚点"},"8":{"title":"图文混排的完整检查顺序","navigationLabel":"图文混排的完整检查顺序"}},"pointGroups":[{"title":"对象身份与环绕","indices":[3,0,1,4]},{"title":"默认值与位置条件","indices":[6,2,7]},{"title":"完整操作与排查","indices":[8]},{"title":"真题入口辨析","indices":[5]}],"searchAliases":["嵌入式能选中","浮动式","穿越型","上下型","衬于文字下方","浮于文字上方","对象锚点"]},{"id":"syllabus-word-screen-clipping","chapter":3,"section":"3.5","origin":"syllabus","topic":"考纲补充","title":"Word截图可插入完整窗口或局部区域","conclusion":"先打开要截取的程序窗口且不要将其最小化，再把Word光标放到插入位置，选择插入→插图→屏幕截图。","points":["在“可用视窗”点缩略图可插入整个窗口；选择“屏幕剪辑”后拖出矩形区域，可只截需要的一部分。","教学示例：为实验报告加入设置对话框，只截对话框内容，插入后再调图片大小与环绕。屏幕截图是画面快照，源窗口后来改变时它不会自动同步。"],"boundary":"截图中的文字通常仍是图片像素，不自动变成可编辑正文；未最小化是可用视窗捕获的条件。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"截图插入后是图片对象；继续设置尺寸和裁剪范围，不能把截图文字当作可直接编辑的正文。"}]},{"q":54,"target":null,"chapter":3,"section":"3.5","topic":"艺术字","title":"用艺术字创建弯曲、描边和填充的装饰文字","conclusion":"艺术字是可编辑的文字对象，可设置文字填充、轮廓和文字效果；弯曲文字应使用文字效果中的转换。","points":["“插入→艺术字”创建对象并输入文字。","选中艺术字后，在绘图工具格式中调整文字效果；跟随路径/转换改变文字排列形态。","普通字符加粗或放大不会让整段文字沿弧线排列。","先选中已有文字，再从插入→艺术字选择样式，可将所选文字用于艺术字对象；新建后也能继续修改文字。选外框移动整个对象，进入文字区修改字符；先分清当前选择层级，再操作填充、轮廓和文字效果。","2022年第54题问实现图示装饰文字的最优操作；应区分艺术字的文字效果与文本框的形状样式。文字填充改变字内部，文字轮廓改变字边缘，文字效果→转换改变排列路径；不要误用形状填充/形状效果替代文字选项。完成后再检查尺寸、环绕与是否压住正文。"],"boundary":"文字效果与形状效果不同；艺术字仍可改文字，转成图片后不再是同一编辑对象。","type":"操作","trigger":"从艺术字的判断与应用整理。","id":"y2022q54","sources":[{"year":2022,"q":54,"type":"操作"}],"keys":["2022-54"],"related":[{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"艺术字可与图片、形状组合，但要选对象外框，不能停留在文字编辑状态。"},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"PowerPoint艺术字同样保留文字填充、旋转与组内编辑能力，可迁移对象选择思路。"}],"pointPresentation":{"0":{"title":"插入艺术字","navigationLabel":"插入艺术字"},"1":{"title":"在文字效果中设置转换","navigationLabel":"在文字效果中设置转换"},"2":{"title":"普通字符格式不能代替路径","navigationLabel":"普通字符格式不能代替路径"},"3":{"title":"把已有文字变为艺术字","navigationLabel":"把已有文字变为艺术字"},"4":{"title":"按真题分别设置文字与外观","navigationLabel":"按真题分别设置文字与外观"}},"pointGroups":[{"title":"建立对象并编辑文字","indices":[0,3]},{"title":"路径、填充与轮廓","indices":[1,2,4]}]},{"q":36,"chapter":3,"section":"3.5","type":"判断","topic":"图形组合","title":"形状可以与图片、艺术字组合","trigger":"题目判断Word中的形状能否与图片或艺术字组合成整体。","conclusion":"形状、图片、艺术字可作为一个组整体操作。先把图片设为非嵌入型环绕，按Ctrl选择至少两个可组合对象，再使用组合命令。","points":["按住Ctrl逐个选择对象外框；点击对象内部文字会进入文字编辑，不能代替选中对象。","入口：图片工具→格式，或绘图工具→格式→排列→组合→组合。按钮不可用时，先检查是否至少选中两个对象，并逐个确认环绕方式都不是嵌入型；这个条件不只针对图片，也适用于可设置环绕的形状和艺术字。","组合后可统一移动、缩放和旋转；先选组合再选其中对象，仍可修改组内对象，也可取消组合后分别编辑。","对象还应处于可共同选择的文档区域；正文对象与页眉中的对象不能直接当作同一组选择。","插入→形状，选矩形、椭圆等后在文档中拖动绘制；绘制相应矩形/椭圆时按住Shift可约束为正方形/正圆。不要把Shift效果泛化为所有形状都变成同一种几何图形。画好后单击外框，使用大小控点调整、旋转控点旋转；若正在编辑形状内文字，先退出文字选区再操作对象。","选中形状后，绘图工具→格式中用形状填充改变内部，用形状轮廓改变边线；需要精确尺寸或旋转角度时检查大小/旋转设置。需要在支持文字的形状内输入文字时，右键形状→添加文字/编辑文字；框内字符另按文字格式处理，改字体颜色不等于给形状填充颜色。修改大小、旋转、层级、环绕分别解决不同问题，完成后逐项核对。","插入→文本框，按需要选预设或绘制文本框；需要竖排时选绘制竖排文本框等对应入口。框内文字属于文本框自己的文字区域，框外仍是正文。单击框内编辑文字，单击边框选择整个对象；网页表单中的输入框只是输入控件，不能据此外推Word文本框的排版规则。","选文本框外框后移动、调整大小或旋转对象；只选框内文字时调整字符、段落格式。需要调整文字方向时，可右键文本框边框→设置形状格式→布局与属性→文本框→文字方向；横排/竖排、旋转整个框与改变字体不是同一动作。更改框大小后要检查内容是否溢出，不能把被遮住的文字当作自动删除。","准备来源框和可接收文字的空文本框，选择来源框，在绘图工具→格式→文本→创建链接，再单击目标框。内容放不下时可沿链接继续流入下一个框；目标已有文字、已被链接或对象不支持文字等条件可能使链接无效，应先检查对象而非连续重复点击。链接是文本流关系，不是把两个对象组合为一个，也不是把正文自动复制成两份。","要解除向后链接，先选相应文本框，再使用断开链接命令，随后检查前后框及整条链中的文字。断开中间的向后链接会把链分开，文字仍保留在前一段链，不能假定后框会各自原地留下断开前看到的文字。来源框容量不足时可能只能看到部分内容；要保留文字，先检查容量与流向，再决定如何分配。","Ctrl或Shift逐个单击可共同选择的对象外框；若其中有嵌入型图片，先单独选择它并改为合适的非嵌入环绕，再回到多选；能够单选并不意味着已经满足多选与组合条件。还要确认对象处于同一可共同选择的文档区域，别把不同页眉/正文里的对象强行视为一个选区。","确认选中至少两个合适对象后执行组合，再移动组合外框：成员应整体移动，相对位置保持；未选中对象不应无故加入。需要独立操作时可取消组合，成员仍留在各自当前的位置。组内可以继续选择成员编辑；组合不把文字变成普通正文，也不把整组自动压成一张不可编辑图片。"],"boundary":"组合不等于合并成一张位图，不会自动删除原对象的可编辑属性；不同对象类型仍有各自限制。","id":"y2026q36","sources":[{"year":2026,"q":36,"type":"判断"}],"keys":["2026-36"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按字符排布，组合前需理解并调整它的环绕方式。"},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"组合管理整体操作，叠放顺序管理前后遮挡；组合本身不会自动修正可见关系。"}],"pointGroups":[{"title":"创建形状并区分对象与文字","indices":[4,5]},{"title":"创建文本框与安排文字流","indices":[6,7,8,9]},{"title":"选择、组合与取消组合","indices":[0,1,3,10,2,11]}],"pointPresentation":{"0":{"title":"选择外框而非内部文字","navigationLabel":"选择外框而非内部文字"},"1":{"title":"组合的入口与前提","navigationLabel":"组合的入口与前提"},"2":{"title":"组合后整体操作与组内编辑","navigationLabel":"组合后整体操作与组内编辑"},"3":{"title":"同一区域才可共同选择","navigationLabel":"同一区域才可共同选择"},"4":{"title":"绘制形状并约束正方或正圆","navigationLabel":"绘制形状并约束正方或正圆"},"5":{"title":"形状填充、轮廓与文字格式","navigationLabel":"形状填充、轮廓与文字格式"},"6":{"title":"插入横排或竖排文本框","navigationLabel":"插入横排或竖排文本框"},"7":{"title":"移动文本框与调整框内文字","navigationLabel":"移动文本框与调整框内文字"},"8":{"title":"链接文本框前先准备空目标框","navigationLabel":"链接文本框前先准备空目标框","blocks":[{"label":"准备与步骤"},{"from":"内容放不下时","label":"结果与失败条件"},{"from":"链接是","label":"与组合的区别"}]},"9":{"title":"断开文本框链接后核对整条文字流","navigationLabel":"断开文本框链接后核对整条文字流"},"10":{"title":"多选前逐个核对布局身份","navigationLabel":"多选前逐个核对布局身份"},"11":{"title":"组合后核对成员与相对位置","navigationLabel":"组合后核对成员与相对位置"}},"searchAliases":["插入形状","正圆","正方形","文本框","竖排文本框","链接文本框","取消组合"]},{"q":56,"chapter":3,"section":"3.5","type":"分析","topic":"对象层级","title":"对象叠放顺序决定箭头是否被形状遮挡","trigger":"两道连续分析题先判断遮挡原因，再要求用绘图工具修复。","conclusion":"浮动对象按层级叠放；矩形位于箭头上层时会遮挡箭头，把箭头置于顶层即可修复。","points":["选择窗格可查看并重排对象层级。","置于顶层或把遮挡对象置于底层都能改变可见关系。","调整层级不会改变对象尺寸和位置。","先选要操作的浮动对象，在图片工具/绘图工具→格式→排列中，上移一层只越过一个相邻对象；置于顶层让它处于相应对象序列最前面。下移一层、置于底层分别相反。当前已在顶端时再上移不会产生新层级；可通过选择窗格核对顺序，别把按钮点击次数当成对象一定显露的证据。","遮挡使鼠标难以直接点中目标时，用选择窗格按名称选择，再调整层级；同时观察遮挡对象是谁。把箭头上移到遮挡它的形状前，或把该形状下移，都可能解决箭头被挡的问题；让箭头透明、改变环绕或直接组合并不等于改变这两者的相对层级。组合后也要分别理解组与外部对象、组内成员的关系。","“衬于文字下方/浮于文字上方”描述对象相对正文的关系；“上移一层/置于顶层”等描述叠放顺序。需要箭头完整可见时先查它和遮挡形状的层级；需要正文不压图片时再查环绕。某个命令即使暂时让画面看起来相似，也不能替代题目要求的对象关系。"],"boundary":"文字环绕控制对象与正文的关系，不负责两个浮动形状之间的前后层级。","id":"y2025q56","sources":[{"year":2025,"q":56,"type":"分析"},{"year":2025,"q":57,"type":"分析"}],"keys":["2025-56","2025-57"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"改变对象与正文的环绕关系，不能代替两个浮动形状之间的层级调整。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"对象组合后仍可进入组内选择和编辑，必要时先定位被遮挡的成员。"}],"pointPresentation":{"0":{"title":"用选择窗格找到对象","navigationLabel":"用选择窗格找到对象"},"1":{"title":"置顶或置底改变遮挡关系","navigationLabel":"置顶或置底改变遮挡关系"},"2":{"title":"层级改变而位置尺寸不变","navigationLabel":"层级改变而位置尺寸不变"},"3":{"title":"上移一层与置于顶层","navigationLabel":"上移一层与置于顶层"},"4":{"title":"被挡住时先选对对象","navigationLabel":"被挡住时先选对对象"},"5":{"title":"与正文重叠和与图形叠放分开","navigationLabel":"与正文重叠和与图形叠放分开"}},"pointGroups":[{"title":"选对象并调整相对层级","indices":[0,1,3]},{"title":"观察结果与真题排错","indices":[2,4,5]}],"searchAliases":["上移一层","置于顶层","选择窗格","图形遮挡"]},{"id":"syllabus-word-smartart","chapter":3,"section":"3.5","origin":"syllabus","topic":"考纲补充","title":"Word用SmartArt表达步骤或层级","conclusion":"SmartArt把文字组织成流程、层次或关系图。先判断要表达的关系，再选布局；三步办事流程适合流程布局，部门隶属关系适合层次布局。","points":["Word 2016教学示例：插入→插图→SmartArt→流程，选择合适布局，在文本窗格依次输入“登记、审核、归档”。","要增加步骤，先选相邻形状，再到SmartArt工具→设计→添加形状，选择前方或后方；要改全部配色，选SmartArt后更改颜色。先分清选中文字、单个形状还是整幅图。"],"boundary":"SmartArt保持可编辑的结构；把流程截图后插入只得到图片，不能再按SmartArt步骤编辑。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"SmartArt转成图片后只保留画面；可用图片尺寸与裁剪工具调整外观，但不能继续按节点编辑结构。"}]},{"q":7,"chapter":3,"section":"3.5","type":"单选","topic":"公式工具","title":"Word公式应从“插入→公式”创建和编辑","trigger":"题目辨析Word 2016公式工具的入口、显示方式和结构编辑。","conclusion":"Word 2016应通过“插入→公式”或Alt+=插入公式，随后在公式工具中搭建分数、上下标、根式等结构。","points":["公式既可与正文位于同一行，也可转换为独立显示。","选中已有公式后可继续修改结构、符号与专业/线性显示。","常用公式可以保存到公式库重复使用。","保存为Word 97—2003的.doc时，内置公式会转换为不可直接编辑的图像形式。需要继续编辑公式结构，优先保留.docx；不能把所有看得见的公式都认作可进入公式工具的对象。","插入→公式用于排版可编辑的数学表达式，不会仅因写出算式就自动求值。表格工具→布局→公式则在表格单元格中插入计算域，按所用函数、范围及更新时机显示结果。两处都叫“公式”，必须先看任务是排数学结构还是计算表格数值。"],"boundary":"“插入→对象”可嵌入某些对象，但不是Word内置公式工具的标准入口。","id":"y2023q7","sources":[{"year":2023,"q":7,"type":"单选"}],"keys":["2023-7"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"字符上下标只改选中文字位置；分数、根式等复杂结构应使用内置公式对象。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"需要给公式编号并在正文引用时，应使用题注和交叉引用保持对应关系。"},{"id":"y2024q8","label":"Word表格：建表、改结构、转换、公式与排序","reason":"表格计算域与插入的数学表达式入口和结果不同。"}],"pointGroups":[{"title":"创建并编辑数学结构","indices":[0,1,2]},{"title":"对象兼容与计算边界","indices":[3,4]}],"pointPresentation":{"4":{"title":"数学表达式与表格计算不是同一工具","navigationLabel":"数学表达式与表格计算不是同一工具"}}},{"q":71,"target":null,"chapter":3,"section":"3.6","topic":"文档保护","title":"打开密码、修改密码与区域限制，要按对象区分","conclusion":"先区分要防止阅读、限制保存原文件，还是只允许修改指定区域。打开密码、修改密码、只读建议和限制编辑的对象不同；一种设置解除后，其他限制不一定同时解除。","points":["“审阅→限制编辑→仅允许此类型编辑→不允许任何更改（只读）”。","选中允许改动的正文，并设置例外用户；不要把需保护的表格加入例外。","启动强制保护后再测试：正文可改、表格不可改。需密码时妥善保管。","要避免他人读取内容，检查打开密码或按身份授权；要允许查看而限制保存回原文件，检查修改密码或只读状态；要只开放正文中的部分区域，检查限制编辑及例外。这些是不同机制的典型用途，不能仅凭“不能修改”四个字就认定原因。备份和自动恢复用于降低丢失风险，不代替访问保护。","打开要保护的文档，依次选择文件→信息→保护文档→用密码进行加密。输入密码并再次确认，保存文件后关闭，再重新打开核对。未通过打开密码时不能正常进入该加密文档；通过后是否可编辑，还取决于其他限制。已知密码并成功打开后，回到加密对话框清空密码、确定并保存，再次打开核对。这不是审阅中的“停止保护”。应妥善保管密码，Word不能直接替普通用户找回遗忘的打开密码。","仅设修改密码、没有同时设置打开密码或身份访问限制时，未提供修改密码仍可选择只读打开。读者能查看内容；只读不应解释成任何文字都绝对不能输入，更不等于禁止复制或另存副本。F12打开另存为，检查工具→常规选项中的“修改文件密码”。该具体Windows版中文入口由官方另存为参数与旧版界面资料交叉支持，仍待原生Word2016复核。输入并确认修改密码，保存后重新打开，分别核对获准修改和只读打开两种结果。要解除，应先以获准修改方式打开，在相应密码设置中清空修改密码并保存；不要用停止区域保护替代。","只读建议是在打开时建议用户采用只读方式；用户可拒绝，在没有其他限制时继续编辑。它不等于打开密码，也不独立提供加密保护。在另存为的常规选项检查“只读建议”，勾选或取消后保存并重新打开核对。此中文入口与修改密码一样，保留Word2016原生复核限定。“标记为最终状态”也偏向提示完成、减少误改，不能当安全加密。看到只读提示后仍要辨明具体原因，不把不同只读机制当成同一个开关。","只有配置限制而未启动强制保护，不能认定已锁定。2022年第71题没有明确要求正文仍可编辑；这里在“正文需要可改、表格不可改”的附加前提下，按本卡前面三步把允许改动的正文列为例外，表格留在受限区域。“每个人”指所有能打开文档的人均可编辑该例外区域；也可按支持的身份方式指定用户。用查找下一个可编辑区域或显示所有可编辑区域定位，不会因此获得新权限。启动强制保护可选择设置密码，也可不设密码。不设密码仍可限制编辑，但任何人都能停止保护。解除入口为审阅→限制编辑→停止保护；若提示密码，输入原保护密码。停止成功后再试改受限内容；取消或密码错误不应解除保护。这里保护的是Word文档区域，不是Excel的保护工作表命令，也没有独立的“表格密码”按钮。","信息权限管理（IRM）可按身份授予阅读、修改、打印、复制等权限。能阅读不代表被允许打印或复制，应检查当前文档实际授予的权限。从文件→信息→保护文档检查限制访问及权限信息；它需要相应账号、许可与授权服务，组织策略也可能限制选项，不是每台Word都能直接启用的本地密码开关。由文档所有者或获完全控制权限者按权限设置修改授权；若受组织策略限制，还需相应管理配置。不能用清空打开密码或停止限制编辑推定IRM已解除。本节仅作作用范围辨析，不模拟账号服务。"],"boundary":"仅设修改密码且无其他限制时，可以只读打开；这不保证所有副本都不能编辑。普通限制编辑也不等于打开加密。多个保护机制叠加时，须分别判断访问、编辑区域与保存权限。","type":"综合","trigger":"2022年第71题只写不允许修改表格数据，没有明确要求正文仍可编辑；配套参考答案的“选择表格后，设置保护密码”是简写，不能据此杜撰独立的保护表格命令。下面的正文例外方案采用“正文仍需可改”的附加前提。","id":"y2022q71","sources":[{"year":2022,"q":71,"type":"综合"}],"keys":["2022-71"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"Word区域限制编辑与文件属性、目录权限属于不同层级，不能用只读属性替代正文例外。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"限制编辑决定能否修改，修订决定如何记录与处理修改，两者解决不同协作问题。"}],"pointPresentation":{"0":{"title":"设置只读编辑限制","navigationLabel":"设置只读编辑限制"},"1":{"title":"把可编辑正文列为例外","navigationLabel":"把可编辑正文列为例外"},"2":{"title":"启动后分别试改正文和表格","navigationLabel":"启动后分别试改正文和表格"},"3":{"title":"先按保护目标选择机制","navigationLabel":"先按保护目标选择机制","blocks":[{"label":"判断对象"},{"label":"条件","from":"这些是不同机制的典型用途，不能仅凭“不能修改”四"}]},"4":{"title":"设置与解除打开密码","navigationLabel":"设置与解除打开密码","blocks":[{"label":"设置"},{"label":"结果","from":"未通过打开密码时不能正常进入该加密文档；通过后是"},{"label":"解除","from":"已知密码并成功打开后，回到加密对话框清空密码、确"},{"label":"限制","from":"这不是审阅中的“停止保护”。应妥善保管密码，Wo"}]},"5":{"title":"修改密码限制保存原文件","navigationLabel":"修改密码限制保存原文件","blocks":[{"label":"作用范围"},{"label":"入口与待核验","from":"F12打开另存为，检查工具→常规选项中的“修改文"},{"label":"设置与解除","from":"输入并确认修改密码，保存后重新打开，分别核对获准"}]},"6":{"title":"只读建议不是强制密码","navigationLabel":"只读建议不是强制密码","blocks":[{"label":"结果"},{"label":"设置与取消","from":"在另存为的常规选项检查“只读建议”，勾选或取消后"},{"label":"易混","from":"“标记为最终状态”也偏向提示完成、减少误改，不能"}]},"7":{"title":"从区域例外到启动和停止保护","navigationLabel":"从区域例外到启动和停止保护","blocks":[{"label":"前提"},{"label":"用户与范围","from":"“每个人”指所有能打开文档的人均可编辑该例外区域"},{"label":"停止","from":"启动强制保护可选择设置密码，也可不设密码。不设密"},{"label":"结果与限制","from":"停止成功后再试改受限内容；取消或密码错误不应解除"}]},"8":{"title":"权限限制按身份和授权判断","navigationLabel":"权限限制按身份和授权判断","blocks":[{"label":"用途"},{"label":"入口与前提","from":"从文件→信息→保护文档检查限制访问及权限信息；它"},{"label":"解除边界","from":"由文档所有者或获完全控制权限者按权限设置修改授权"}]}},"comparison":{"headers":["机制（单独设置时）","能否读取","修改和解除边界"],"rows":[["打开密码","正常打开需通过密码","清空加密密码并保存；不自动解除其他限制"],["修改密码","可选择只读打开","限制保存回原文件；副本与其他权限另查"],["只读建议","可以读取","可拒绝建议；不等于强制授权"],["限制编辑＋正文例外","可以读取","例外区域按授权编辑；停止保护另行验证"],["IRM权限","依身份授权","编辑、复制、打印分别看权限和策略"]]},"pointGroups":[{"title":"分清保护对象","indices":[3,4,5,6]},{"title":"限制编辑的完整流程","indices":[0,1,2,7]},{"title":"按身份限制访问","indices":[8]}],"searchAliases":["只锁表格、保留正文可编辑，需要设置编辑例外","打开密码","修改文件密码","只读推荐","只读建议","限制部分编辑","不能打开","停止保护","IRM"]},{"id":"syllabus-word-print-controls","chapter":3,"section":"3.6","origin":"syllabus","topic":"考纲补充","title":"打印先定范围，再定份数、纸面和标记","conclusion":"文件→打印先预览，再选打印机、份数和打印范围。普通连续页码可写2-4；要打印第2页及第5至7页，可写2,5-7。分节重新编号时应核对预览，不能只凭页码外观推断物理页。","points":["单面/双面控制纸张两面的使用方式；自动双面需要打印机支持，手动双面按提示重新放纸。先用少量页面测试翻纸方向。","含修订或批注的文档，要在打印设置核对“打印标记”，并用预览确认输出是否带标记；不打印标记并不等于已接受全部修订。","教学示例：打印两份第2至4页、不带批注的报告，应分别设置份数2、范围2-4及标记选择，再检查预览。","打开目标文档，选择文件→打印，或按Ctrl+P。在打印界面选择打印机，翻页或调整预览比例，检查即将输出的版面。若已把“打印预览和打印”添加到快速访问工具栏，也可从该按钮进入；“快速打印”会直接提交打印，不能当作先预览的同义入口。预览区用于检查，不在其中修改正文或字符、段落格式；发现正文问题先返回文档编辑。仍可在打印设置调整方向、纸张和页边距。预览多页或放大查看不等于把多页合印到一张纸。","打印所有页针对全文；打印当前页应核对打印预览中当前显示的页面，不机械等同于刚才编辑光标所在页。只打印某段时，先在正文建立实际选区，再进入文件→打印并选择打印所选内容。输出对象是选中的内容，不是这些文字所在的整页；没有选区时不要把该命令当可用。切换范围后重新核对预览，尤其要区分“第3页”和“第3页中的一段”。正文因编辑重新分页时，也要重新确认目标。","普通连续编号时，用英文逗号分隔离散页码，用连字符指定连续范围。例如2,5-7表示第2页和第5至7页，共4页；1-3,5,9,11-13表示8个页面。分节重新编号时要结合节和预览确认实际页面，不能把显示页码直接当文件中的物理页位置。详细分节打印语法本批未获足够适用官方依据，保留待核验。仅打印奇数页或偶数页是范围筛选，不等于自动双面；需要配合重新放纸时按打印机说明少量试印。","以第1至3页、两份、单面为例：逐份打印按1、2、3、1、2、3输出；不逐份则按1、1、2、2、3、3分组。份数指整套所选内容的副本数，不是让页码变多。每张纸多页把多个文档页缩排到同一纸面；单双面决定是否使用纸张背面。它们与份数、逐份顺序分别控制不同结果。若每面一页、每份单独开始、不加文档属性等附加页，3页双面每份需2张纸，两份需4张。驱动拼版、跨份排纸或额外页面不在此例中，不能无条件套公式。","先核对范围，再核对份数和逐份顺序、单双面与每张纸页数、方向与纸张、标记。改变设置后重新看预览，确认无误再单击打印；返回编辑本身不会提交任务。彩色、灰度、自动双面等可能在打印机属性中，取决于所选设备和驱动；换打印机后需要重新核对。文件→选项→显示→打印选项还能控制部分对象及打印前更新域。屏幕上看见的内容、打印标记和校对提示并不都按相同规则输出；已有对象与校对卡保留具体解释。"],"boundary":"份数、页码范围、每张纸页数和单双面是不同设置；不要用其中一项替代另一项。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"y2022q71","label":"先检查文档是否允许打印","reason":"IRM可分别限制阅读、打印和复制；能打开不等于能打印，先辨认权限再设置输出。"}],"pointPresentation":{"0":{"title":"单双面和实际翻纸条件","navigationLabel":"单双面和实际翻纸条件"},"1":{"title":"打印标记不等于处理修订","navigationLabel":"打印标记不等于处理修订"},"2":{"title":"两份指定页面的操作示例","navigationLabel":"两份指定页面的操作示例"},"3":{"title":"进入打印预览并返回编辑","navigationLabel":"进入打印预览并返回编辑","blocks":[{"label":"主入口"},{"label":"其他入口","from":"若已把“打印预览和打印”添加到快速访问工具栏，也"},{"label":"结果与限制","from":"预览区用于检查，不在其中修改正文或字符、段落格式"}]},"4":{"title":"全部、当前页与所选内容","navigationLabel":"全部、当前页与所选内容","blocks":[{"label":"对象"},{"label":"所选内容","from":"只打印某段时，先在正文建立实际选区，再进入文件→"},{"label":"验收","from":"切换范围后重新核对预览，尤其要区分“第3页”和“"}]},"5":{"title":"自定义页码及奇偶页筛选","navigationLabel":"自定义页码及奇偶页筛选","blocks":[{"label":"操作"},{"label":"限制","from":"分节重新编号时要结合节和预览确认实际页面，不能把"},{"label":"其他选择","from":"仅打印奇数页或偶数页是范围筛选，不等于自动双面；"}]},"6":{"title":"份数、逐份与每张纸页数","navigationLabel":"份数、逐份与每张纸页数","blocks":[{"label":"完整例子"},{"label":"不同设置","from":"每张纸多页把多个文档页缩排到同一纸面；单双面决定"},{"label":"计算条件","from":"若每面一页、每份单独开始、不加文档属性等附加页，"}]},"7":{"title":"核对打印机和输出后再打印","navigationLabel":"核对打印机和输出后再打印","blocks":[{"label":"检查顺序"},{"label":"硬件限制","from":"彩色、灰度、自动双面等可能在打印机属性中，取决于"},{"label":"相关选项","from":"文件→选项→显示→打印选项还能控制部分对象及打印"}]}},"pointGroups":[{"title":"进入预览与选定内容","indices":[3,4,5]},{"title":"份数、纸面和标记","indices":[6,0,1]},{"title":"完整操作与输出核对","indices":[2,7]}],"searchAliases":["打印当前页","打印所选内容","打印自定义页码","逐份打印","打印预览","快速打印","打印奇数页"]},{"q":5,"chapter":3,"section":"3.7","type":"单选","topic":"题注与引用","title":"题注与交叉引用要配合使用","trigger":"真题从自动表号、图表编号和“先题注、后引用”的操作顺序考查长文档引用。","conclusion":"先为图、表或公式插入题注，再在正文中用交叉引用插入编号，才能在对象增删后统一更新。","points":["为图、表或公式设置自动题注：选择对象→引用→插入题注，确定标签、编号格式和位置；题注编号由域管理。","正文引用图号：引用→交叉引用，选择对应题注及所需内容，例如“仅标签和编号”。选为超链接可支持跳转，但跳转选项不是编号关系本身。","新增、删除或移动对象后，先更新题注编号，再更新引用它的交叉引用域；可选择相关域按F9。跨不同文档区域时要分别核对。","题注还可用于生成图表目录；手工输入的“表1”只是一段普通文字，不会建立自动题注、交叉引用和图表目录的关联。","题注为“表1　人口统计”时，整项题注包含标签、编号和说明；只有标签和编号得到“表1”；只有题注文字得到“人口统计”。题目要求正文出现表号时，不能选择只输出说明文字。先确保目标题注已存在，再把光标放到正文引用位置。打开引用→交叉引用，依次核对引用类型、引用内容和具体题注，再插入；插入→链接组也提供交叉引用入口。选择“插入为超链接”增加跳转能力，不负责建立一个尚不存在的题注，也不保证编号随任何编辑立即刷新。2026年题目的关键就在引用内容与目标的选择，不能只背步骤序号。","先给需收录的图或表插入题注；将光标放在目录位置，选择引用→题注组→插入表目录，核对题注标签和显示选项后确定。选择“图”标签可得到图目录，选择“表”标签可得到表目录；这里的表目录并不只针对数据表格。列表依据题注组织，并可显示所在页码。选中生成的图表目录，用引用中的更新命令或F9。仅分页变化可更新页码；题注增删或说明改变，应更新整个目录。不要在目录结果中逐个手改编号来代替维护题注。","本章“Word视图、标题结构与导航窗格”卡已经提供建立层级→插入自动目录→按变化类型更新的完整流程；本节与图表目录对照使用，不另维护一套标题正文。课堂列出的标题层级入口还有大纲视图、段落对话框和引用→目录组→添加文字；应核对选中标题的实际层级，不能把各入口一概理解为相同的外观修改。手动目录只是手填结果，不能替代自动收集标题。在默认跟随链接设置下，Ctrl+单击目录项可跳转到目标。引用→目录→删除目录针对目录对象；正文标题仍是另一个对象。只想不显示目录时，不要连同正文标题一起删除。","域保存指令并显示结果：题注序号通常用SEQ，交叉引用可用REF等，目录用TOC，邮件合并字段用MERGEFIELD。外观相同的普通文字没有这些关系；不能把所有引用都说成只有一种域。Ctrl+F9建立空域，仍须输入适用代码；直接键入大括号不是建立域。Shift+F9切换所选域代码与结果，Alt+F9切换全部域的代码显示；F9才是更新所选域。Ctrl+Shift+F9用于解除可解除域的链接，把最近结果留下作为静态内容，之后不能靠原域关系更新；它不只是去掉目录超链接。部分特殊域不支持这样解除，不能把规则推广到全部域或用SEQ题注作通用示例。目录和引用变成静态文字后，要重新建立相应关系才能继续动态更新。普通域的锁定只阻止该域更新，不等于文档加密或限制编辑；本批不展开全部域类型。","题注或引用结果过旧时，先确认目标仍存在，再更新源编号和依赖它的引用。选中相关域按F9，或右击更新域；批量选择更新后仍要分别核对表格、页眉页脚等不同区域。文件→选项→显示→打印选项可选择打印前更新域。这说明更新时机还与域类型及选项有关，不能写成“所有域都实时更新”或“所有域只能手动更新”。出现找不到引用源时，先检查目标题注或书签是否被删除。反复按F9不能重新创造已经不存在的目标，也不能把普通文字恢复为原来的域。","选中文字、图片或单击目标位置，选择插入→书签，输入名称并添加。例如用字母开头的Report_1；名称不要含空格，可用下划线。课堂一次中文输入失败不能证明Word一概不支持中文书签。按Ctrl+G打开定位，选择书签及名称后转到对应位置；书签也可作为超链接目标，用于再次回到同一位置。在书签列表删除名称与删除所标记的正文不同。若删除正文或书签，已有引用应重新核对；不要把删除一个名称理解为自动清理所有引用。"],"boundary":"自动题注管理对象编号，交叉引用引用已有目标；这两个步骤缺一时，正文编号都可能与对象不一致。","version":"已转换为Word 2016","id":"merged-6","sources":[{"year":2020,"q":5,"type":"单选"},{"year":2023,"q":54,"type":"操作"},{"year":2026,"q":48,"type":"操作"},{"year":2021,"q":6,"type":"单选","page":2}],"keys":["2020-5","2023-54","2026-48","2021-6"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"自动目录依赖标题，图表目录依赖题注；先建立结构再生成目录，手输编号不够。"},{"id":"y2024q8","label":"Word表格的转换、计算、排序与删除","reason":"Word表格公式也是域，可与题注引用一起理解源内容变化后的更新操作。"},{"id":"y2022q55","label":"脚注在页底，尾注通常在文末或节末","reason":"题注给图表编号，脚注补充说明，先按用途选择对象再插入引用。"}],"pointGroups":[{"title":"建立题注与交叉引用","indices":[0,1,4]},{"title":"按结构生成两类目录","indices":[3,5,6]},{"title":"域的更新与解除","indices":[2,7,8]},{"title":"为位置建立书签","indices":[9]}],"pointPresentation":{"0":{"title":"建立自动题注","navigationLabel":"建立自动题注"},"1":{"title":"插入正文交叉引用","navigationLabel":"插入正文交叉引用"},"2":{"title":"源编号变化后更新引用","navigationLabel":"源编号变化后更新引用"},"3":{"title":"图表目录的结构来源","navigationLabel":"图表目录的结构来源"},"4":{"title":"选择引用内容，核对完整输出","navigationLabel":"选择引用内容，核对完整输出","blocks":[{"label":"例子"},{"label":"步骤","from":"先确保目标题注已存在，再把光标放到正文引用位置。"},{"label":"限制","from":"选择“插入为超链接”增加跳转能力，不负责建立一个"}]},"5":{"title":"生成并更新图表目录","navigationLabel":"生成并更新图表目录","blocks":[{"label":"操作"},{"label":"结果","from":"选择“图”标签可得到图目录，选择“表”标签可得到"},{"label":"更新","from":"选中生成的图表目录，用引用中的更新命令或F9。仅"}]},"6":{"title":"普通目录沿标题结构生成","navigationLabel":"普通目录沿标题结构生成","blocks":[{"label":"学习入口"},{"label":"课堂补充","from":"课堂列出的标题层级入口还有大纲视图、段落对话框和"},{"label":"跳转与删除","from":"在默认跟随链接设置下，Ctrl+单击目录项可跳转"}]},"7":{"title":"域身份、显示、更新与解除","navigationLabel":"域身份、显示、更新与解除","blocks":[{"label":"对象"},{"label":"操作区别","from":"Ctrl+F9建立空域，仍须输入适用代码；直接键"},{"label":"解除边界","from":"Ctrl+Shift+F9用于解除可解除域的链接"},{"label":"检查","from":"目录和引用变成静态文字后，要重新建立相应关系才能"}]},"8":{"title":"更新前先检查目标和范围","navigationLabel":"更新前先检查目标和范围","blocks":[{"label":"顺序"},{"label":"条件","from":"文件→选项→显示→打印选项可选择打印前更新域。这"},{"label":"故障","from":"出现找不到引用源时，先检查目标题注或书签是否被删"}]},"9":{"title":"书签命名、定位与删除","navigationLabel":"书签命名、定位与删除","blocks":[{"label":"建立"},{"label":"使用","from":"按Ctrl+G打开定位，选择书签及名称后转到对应"},{"label":"删除边界","from":"在书签列表删除名称与删除所标记的正文不同。若删除"}]}},"searchAliases":["只有标签和编号","只有题注文字","插入表目录","图目录","自动目录更新","取消目录链接","解除域","Ctrl+Shift+F9","书签定位"]},{"q":55,"chapter":3,"section":"3.7","type":"操作","topic":"页码域","title":"在形状中放置光标后插入PAGE域","trigger":"题目要求把页码显示在页眉中的平行四边形形状内。","conclusion":"先进入页眉并在形状文字区内放置插入点，再用“页码→当前位置”或插入PAGE域，页码才会成为形状内的动态内容。","points":["“页面顶端”图库会在预设页眉位置新建页码对象，不保证进入现有形状。","PAGE域显示当前页码，NUMPAGES域显示总页数。","页眉中的形状会随页眉重复，但节之间可有不同设置。","用域代码插入时，在形状文字区按Ctrl+F9建立域括号，输入PAGE后按F9更新；若显示的是代码，可按Shift+F9切换当前域的代码与结果。直接键入“{ PAGE }”只是文字，不会生成页码域。","保留形状文字区内的插入点，在插入→文本→文档部件→域中选择PAGE并确定；也可在页眉和页脚工具中用“页码→当前位置”。这些入口都要先确认插入点，不能仅选中形状外框。"],"boundary":"先选中形状外框与把光标放进形状文字区是不同状态；只有后者能把页码插到形状内部。","id":"y2024q55","sources":[{"year":2024,"q":55,"type":"操作"}],"keys":["2024-55"],"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"PAGE域显示的页码仍受当前节的起号、页眉页脚类型及链接状态影响。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"自动页码、题注和交叉引用都由域生成动态内容，不能用手输数字替代。"}],"pointGroups":[{"title":"确认位置与域的结果","indices":[0,1,2]},{"title":"两个域插入入口","indices":[3,4]}],"pointPresentation":{"3":{"title":"快捷键：建立并更新PAGE域"},"4":{"title":"通过对话框插入PAGE域","navigationLabel":"通过对话框插入PAGE域"}}},{"q":55,"target":null,"chapter":3,"section":"3.7","topic":"脚注与尾注","title":"脚注通常在页底，尾注位置与编号须看设置","conclusion":"脚注和尾注由正文引用标记连接说明内容；插入引用后由Word管理编号。","points":["光标放在需解释的文字后，使用“引用→插入脚注”。","新增、移动或删除正文中的引用标记时，编号可自动重新安排。","脚注/尾注用于补充说明；批注用于审阅交流，题注用于给图表编号。","把光标放在需要补充说明的文字后，选择引用→插入脚注或插入尾注，再在相应注释区输入说明。正文标记与注释内容是一对关联对象。可双击注释前的标记返回正文引用处。脚注和尾注都能解释局部文字，不能用“脚注只解释局部、尾注只能解释全文”作排他定义。","在引用→脚注组打开脚注和尾注对话框，核对位置、编号格式、起始编号、编号方式和应用范围，再应用到需要的文档或节。脚注常见于页面底端，也可设为文字下方；尾注常见于文档末尾，也可设为节的末尾。仅凭截图位于底部或某个页边距符号，不能作为唯一判断依据。脚注可按连续、每页或每节重新编号的设置核对；尾注检查连续或每节重新编号及应用范围，不把脚注的每页重编选项推广到尾注。不能把练习中的“可独立编号”当默认必然如此。自动编号会管理次序，自定义符号不等于同样的自动连续编号。","在脚注和尾注对话框选择转换，按需要将全部脚注转为尾注、全部尾注转为脚注，或交换两者。转换后核对正文引用、注释位置和编号设置。剪贴说明文字并不等于转换注释类型；单条右键转换的具体Word2016入口本批未完成原生核验。","在正文选择对应脚注或尾注的引用标记，再按Delete；随后检查对应说明是否删除，以及后续自动编号是否按设置重新排列。只清空页底或文末的注释文字，可能留下引用标记和空注释。要改说明内容可以编辑注释区，要删除这条注释则应处理正文标记。"],"boundary":"删除注释应删除正文中的引用标记，不能只擦掉页底说明文字。","type":"操作","trigger":"从脚注与尾注的判断与应用整理。","id":"y2022q55","sources":[{"year":2022,"q":55,"type":"操作"}],"keys":["2022-55"],"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"脚注引用连接说明，交叉引用连接题注目标，均应管理引用关系而非手工写显示编号。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"脚注属于正文的补充说明，批注用于审阅交流，二者在交付文本中的角色不同。"}],"pointPresentation":{"0":{"title":"在正文引用处插入脚注","navigationLabel":"在正文引用处插入脚注"},"1":{"title":"正文标记与自动编号","navigationLabel":"正文标记与自动编号"},"2":{"title":"脚尾注、批注和题注的用途","navigationLabel":"脚尾注、批注和题注的用途"},"3":{"title":"建立引用标记与注释内容","navigationLabel":"建立引用标记与注释内容","blocks":[{"label":"操作"},{"label":"返回与结果","from":"可双击注释前的标记返回正文引用处。脚注和尾注都能"}]},"4":{"title":"位置和编号不是唯一默认","navigationLabel":"位置和编号不是唯一默认","blocks":[{"label":"设置"},{"label":"位置","from":"脚注常见于页面底端，也可设为文字下方；尾注常见于"},{"label":"编号限制","from":"脚注可按连续、每页或每节重新编号的设置核对；尾注"}]},"5":{"title":"转换脚注和尾注","navigationLabel":"转换脚注和尾注","blocks":[{"label":"操作"},{"label":"结果与限制","from":"转换后核对正文引用、注释位置和编号设置。剪贴说明"}]},"6":{"title":"删除引用标记才删除注释","navigationLabel":"删除引用标记才删除注释","blocks":[{"label":"操作"},{"label":"反例","from":"只清空页底或文末的注释文字，可能留下引用标记和空"}]}},"pointGroups":[{"title":"插入与识别注释","indices":[0,3,2]},{"title":"核对位置、编号和转换","indices":[1,4,5]},{"title":"删除完整注释对象","indices":[6]}],"searchAliases":["脚注在页底，尾注通常在文末或节末","脚注文字下方","尾注节末","脚注尾注转换","删除脚注引用标记"]},{"q":56,"chapter":3,"section":"3.7","type":"操作","topic":"修订","title":"修订记录编辑，接受或拒绝决定最终文本","trigger":"题目要求按正确顺序记录教师的插入、删除并形成最终稿。","conclusion":"先打开“审阅→修订”，再进行编辑；完成后逐项接受或拒绝修订，才能形成最终文本。","points":["开始记录：审阅→修订，再编辑正文；插入、删除和格式更改会作为修订保留。关闭修订只停止记录之后的编辑。","所有标记用于查看完整修订；无标记暂时显示采用修订后的清洁效果，但修订记录仍保存在文档中。","接受插入会保留新增文字，拒绝插入会去掉新增文字；接受删除会真正去掉原文字，拒绝删除会恢复原文字。","批注用于说明与讨论，不直接改正文；比较文档用于找出两个版本的差异，与预先开启修订记录后续操作不同。","交付最终文本前，核对并接受或拒绝已有修订。需要停止记录时再关闭修订；不要只切到无标记就认定清理完成。","需要区分审阅者时，在审阅的修订选项中打开高级选项，检查相应修订类型的颜色是否设为按作者，以及插入、删除和格式更改的标记方式。按作者显示有助于区分来源；颜色是显示设置，不是某个人跨文档永远不变的身份编码。开启修订并不意味着每种显示都固定为同一颜色或位置。","简单标记用简洁提示指出修改位置；所有标记用于查看细节；无标记显示采用更改后的外观；原始状态显示未体现修订的外观。这些切换改变显示，不能代替接受或拒绝。使用显示标记、作者或修订类型筛选时，还要确认自己看到的是全部记录还是其中一部分。用上一处、下一处逐项查看，再决定接受或拒绝。全局命令前核对是所有修订还是所有显示的修订；跳到下一处本身不作取舍。","选中需要讨论的文字，选择审阅→新建批注，或按Ctrl+Alt+M，输入意见。作者查看后决定是否修改正文；修订开启时也可同时添加批注。在批注框右击删除，或用审阅→批注组的删除命令处理批注。隐藏批注不等于删除，删除批注也不等于接受正文修订。这里使用课堂Word2016传统批注流程；不把新版的发布按钮或现代评论功能当作2016步骤。交付时分别检查批注、修订和保存后的实际文本。","已有原稿和修改稿但没有预先开启修订时，可用审阅→比较→比较，选择两份文档及比较范围。采用“显示更改于新文档”时，差异放到新文档中供检查；若改为原文档或修订文档，所选文档可能被修改，不能无条件说原稿总不变。多人分别修改同一原稿时，用审阅→比较→合并，选择原始稿和一份修订稿，将结果放在新文档。保存汇总后可继续合入其他审阅副本，最后仍需接受或拒绝修订。比较找两版本差异，合并汇集审阅修订；它们都不等于并排查看，也不是按收件人记录生成文档的邮件合并。"],"boundary":"是否记录新修改、是否显示旧记录、是否接受旧修改是三件事；隐藏显示不能代替处理修订。","id":"y2023q56","sources":[{"year":2023,"q":56,"type":"操作"},{"year":2021,"q":8,"type":"单选","page":3}],"keys":["2023-56","2021-8"],"related":[{"id":"y2022q71","label":"只锁表格、保留正文可编辑，需要设置编辑例外","reason":"开启修订不等于限制修改权限，若需正文可改而表格受保护，还要设置编辑例外。"},{"id":"y2023q55","label":"校对波浪线提示可能的问题，不属于打印正文","reason":"编辑提示和审阅标记均可被隐藏，但隐藏不意味着错误已改正或修订已接受。"}],"pointGroups":[{"title":"开始记录并选择显示方式","indices":[0,5,1,6]},{"title":"处理修订形成最终稿","indices":[2,4]},{"title":"批注、比较和合并审阅","indices":[3,7,8]}],"pointPresentation":{"0":{"title":"开启或关闭新修改记录","navigationLabel":"开启或关闭新修改记录"},"1":{"title":"无标记仍保留修订","navigationLabel":"无标记仍保留修订"},"2":{"title":"接受与拒绝的实际结果","navigationLabel":"接受与拒绝的实际结果"},"3":{"title":"批注和比较的用途","navigationLabel":"批注和比较的用途"},"4":{"title":"形成最终稿前处理旧修订","navigationLabel":"形成最终稿前处理旧修订"},"5":{"title":"按作者显示修订，不靠颜色猜身份","navigationLabel":"按作者显示修订，不靠颜色猜身份","blocks":[{"label":"设置"},{"label":"结果与限制","from":"按作者显示有助于区分来源；颜色是显示设置，不是某"}]},"6":{"title":"简单、所有、无标记和原始状态","navigationLabel":"简单、所有、无标记和原始状态","blocks":[{"label":"比较"},{"label":"作用范围","from":"这些切换改变显示，不能代替接受或拒绝。使用显示标"},{"label":"完成检查","from":"用上一处、下一处逐项查看，再决定接受或拒绝。全局"}]},"7":{"title":"批注可讨论，但不会自动替换正文","navigationLabel":"批注可讨论，但不会自动替换正文","blocks":[{"label":"操作"},{"label":"清理","from":"在批注框右击删除，或用审阅→批注组的删除命令处理"},{"label":"版本与结果","from":"这里使用课堂Word2016传统批注流程；不把新"}]},"8":{"title":"比较版本与合并审阅稿","navigationLabel":"比较版本与合并审阅稿","blocks":[{"label":"比较"},{"label":"合并","from":"多人分别修改同一原稿时，用审阅→比较→合并，选择"},{"label":"易混","from":"比较找两版本差异，合并汇集审阅修订；它们都不等于"}]}},"searchAliases":["按作者颜色","简单标记","原始状态","删除批注","比较文档","合并修订","关闭修订后仍有删除线"]},{"id":"syllabus-document-coauthor","chapter":3,"section":"3.7","origin":"syllabus","topic":"考纲补充","title":"共同编辑、批注和修订是三种不同协作动作","conclusion":"共同编辑让多人修改同一份共享文档；批注提出问题或意见；修订记录文字的增删改，等待接受或拒绝。发送多个附件副本会形成多份文件，并不等于共同编辑。","points":["Word 2016示例：先把文档保存到OneDrive或SharePoint Online，选择“共享”，核对参与者与可查看/可编辑权限，再把同一文档的链接交给参与者。","协作时观察他人的编辑位置，避免同时改写同一段；用批注讨论，用修订保留需要审阅的改动。结束前核对保存/同步状态与最终版本。","使用在线协作软件时，应核对账号、共享范围和权限；能打开文档不代表有编辑权。版本历史与修订记录用途不同，恢复旧版本后仍需检查是否覆盖了他人的有效修改。"],"boundary":"协同功能受文件格式、保存位置、客户端和账号配置影响；不要把Word 2016的能力直接推广到所有Office 2016组件。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"共同编辑同一文件前，先分清批注只是意见、修订记录更改、接受或拒绝才决定最终文本。"}]},{"q":36,"chapter":3,"section":"3.7","type":"判断","topic":"邮件合并","title":"邮件合并连接数据源，合并域和条件规则生成个性化文档","trigger":"题目判断Word 2016邮件合并的数据源能否选择Word文档。","conclusion":"主文档保存共同内容，数据源按行保存记录，合并域把字段放进指定位置；条件规则可按记录内容生成不同称谓。","points":["数据源可以来自规范的Word表格、Excel、Access、Outlook联系人或文本列表；首行通常是字段名，每条记录对应一个收件人或数据对象。","在邮件→选择收件人→使用现有列表连接数据源，确认表或工作表、字段名及所需收件人，再插入姓名等合并域。","需要按性别生成称谓时，用邮件→规则→如果…那么…否则。字段、比较值和两种输出都要设置，例如性别等于“女”输出“女士”，否则输出“先生”。","预览结果后切换记录，检查姓名、称谓和空缺字段；预览只显示当前记录效果。完成并合并时再选择生成文档、打印或其他合并目标。","生成结果不等于原数据源被改写；也不要把所有收件人的内容手工堆在主文档中。","邀请函、录取通知书等主干相同、姓名或地址不同的多份内容适用邮件合并；它还可用于信封和标签，不是只用来发电子邮件。新建或打开共同正文，选择邮件→开始邮件合并并确定文档类型；本例邀请函选择信函，输入所有收件人共用的内容，并留出字段位置。准备字段名清楚、每行一条记录的名单，不在明细中混入重复表头或小计。先核对数据完整性，再连接；普通散排Word正文不能直接当规范名单。","邮件→选择收件人可使用现有列表、键入新列表，或使用支持的联系人来源。连接后到编辑收件人列表，核对列名与实际数据，按需要勾选、筛选或排序。收件人范围决定哪些记录参加后续合并；取消勾选不是删除原始数据。字段放错位置应在主文档调整，姓名写错则应在有权限的源文件中更正并保存，再刷新列表或依连接情况重新读取。对话框中的源数据编辑可能改动原名单，与勾选、筛选的作用不同；不要靠逐份改预览掩盖来源错误。连接方式、字段格式和数据刷新可能不同；长编号、前导零等应先在来源中保留所需表示。这里不重新展开Excel导入。","将光标放到姓名位置，用邮件→插入合并域选择姓名；需要条件称谓时，选择规则→如果…那么…否则，设置字段、比较、比较值以及两个输出分支，确认后插入。本例性别等于“女”时输出“女士”，否则输出“先生”。空值或未统一写法也会走否则分支，所以“否则”不等于数据已经被验证为男性；应先清理或检查名单。IF规则选择输出文字；“下一记录条件”控制是否推进到另一记录，不能拿它替代性别称谓判断。若只要求把条件域和姓名域都插入正确位置，两者先后可依题面条件安排，不必把一个示例顺序当唯一可行顺序。","切到预览结果，用上一条、下一条检查不同记录，至少核对字段位置、两条条件分支和空缺数据。预览当前收件人不等于已经生成或发送全部结果。邮件→完成并合并，再按任务选择编辑单个文档、打印文档或发送电子邮件等支持的目标。生成新文档时继续选择全部、当前记录或指定记录范围；电子邮件还需要相应地址和客户端条件，本例不展开发送设置。“编辑单个文档”可把多条记录的个性化内容合并到一个新Word文档中，不保证每个收件人自动得到一个独立文件。生成后仍应保存并抽查结果。","保存邮件合并主文档会保留连接信息和合并规则；以后重新打开时仍需数据源可访问，并按实际提示核对连接。保存主文档不等于把外部数据源合并成永久内置副本。本例合并结果采用生成时的普通文字快照。修改新文档中的姓名，不会因此改写原名单；之后修改名单，要重新核对主文档读取的数据并再次合并，不能推定旧结果实时全部同步。若结果另含外部链接或其他域，它们仍有各自的更新规则；本节不把“普通文字快照”推广为任何对象永远互不影响。","规范Word表格可作为邮件合并数据源，微软的Word对象模型明确支持创建和编辑这种数据源。由此不能把“数据源不能是Word文档”作为一般软件规则。2025年第36题的配套未署名答案与这一事实冲突，不能称其为官方裁决，也不据此把现有正确解释改错。判断时同时检查“规范表格”条件，不能反过来声称任意Word文档都能直接合并。"],"boundary":"数据源需要规则的字段和记录；普通散排正文不能直接替代收件人表。字段值为空或拼写不一致时，条件规则可能走到另一分支。","id":"y2025q36","sources":[{"year":2025,"q":36,"type":"判断"},{"year":2022,"q":56,"type":"操作"}],"keys":["2025-36","2022-56"],"related":[{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"收件人表中的长编号须在导入时保留文本类型，精度丢失后邮件合并不能还原。"},{"id":"y2021q50","label":"先提取一位，再判奇偶，最后选择输出","reason":"“如果…那么…否则”与IF同样按条件选择输出，字段值和真、假分支需逐项核对。"},{"id":"y2024q59","label":"格式化为表格同时建立结构化数据区域","reason":"Excel来源需规范列标题与明细记录，建表时核对标题行，可减少姓名等合并字段识别错误。"}],"pointGroups":[{"title":"准备主文档与数据源","indices":[5,0,1,6]},{"title":"放置合并域和条件规则","indices":[2,7]},{"title":"预览、输出与再次使用","indices":[3,8,4,9]},{"title":"Word数据源的真题辨析","indices":[10]}],"pointPresentation":{"0":{"title":"数据源的字段和记录","navigationLabel":"数据源的字段和记录"},"1":{"title":"连接收件人名单","navigationLabel":"连接收件人名单"},"2":{"title":"按字段条件生成称谓","navigationLabel":"按字段条件生成称谓"},"3":{"title":"预览与完成合并不同","navigationLabel":"预览与完成合并不同"},"4":{"title":"生成结果不改写数据源","navigationLabel":"生成结果不改写数据源"},"5":{"title":"先建立共同主文档和变化数据","navigationLabel":"先建立共同主文档和变化数据","blocks":[{"label":"用途"},{"label":"主文档","from":"新建或打开共同正文，选择邮件→开始邮件合并并确定"},{"label":"数据源","from":"准备字段名清楚、每行一条记录的名单，不在明细中混"}]},"6":{"title":"连接后核对字段和收件人范围","navigationLabel":"连接后核对字段和收件人范围","blocks":[{"label":"入口"},{"label":"结果","from":"收件人范围决定哪些记录参加后续合并；取消勾选不是"},{"label":"限制","from":"连接方式、字段格式和数据刷新可能不同；长编号、前"}]},"7":{"title":"插入合并域，再按需使用IF规则","navigationLabel":"插入合并域，再按需使用IF规则","blocks":[{"label":"操作"},{"label":"例子","from":"本例性别等于“女”时输出“女士”，否则输出“先生"},{"label":"边界","from":"IF规则选择输出文字；“下一记录条件”控制是否推"}]},"8":{"title":"逐条预览后选择真正的合并出口","navigationLabel":"逐条预览后选择真正的合并出口","blocks":[{"label":"检查"},{"label":"输出","from":"邮件→完成并合并，再按任务选择编辑单个文档、打印"},{"label":"结果","from":"“编辑单个文档”可把多条记录的个性化内容合并到一"}]},"9":{"title":"保存主文档、数据源与结果的影响范围","navigationLabel":"保存主文档、数据源与结果的影响范围","blocks":[{"label":"主文档"},{"label":"结果","from":"本例合并结果采用生成时的普通文字快照。修改新文档"},{"label":"限制","from":"若结果另含外部链接或其他域，它们仍有各自的更新规"}]},"10":{"title":"核对Word表格数据源的题目争议","navigationLabel":"核对Word表格数据源的题目争议","blocks":[{"label":"软件依据"},{"label":"题面与答案","from":"2025年第36题的配套未署名答案与这一事实冲突"}]}},"searchAliases":["主文档数据源","Word文档作为数据源","编辑收件人列表","合并域","下一记录条件","编辑单个文档","完成并合并","邮件合并保存结果"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
